/**
 * genMegaBulk.js - generates mega_bulk.json with 4000+ entries
 * Covers all major Indian law acts exhaustively
 * Run: node backend/data/genMegaBulk.js
 */
'use strict';
const fs   = require('fs');
const path = require('path');
const OUT  = path.join(__dirname, 'mega_bulk.json');

const all = [];

function add(act, short, section, title, desc, chapter, chapterTitle, category, keywords) {
  all.push({
    act, act_short: short, section: String(section),
    section_title: title, section_desc: desc,
    chapter: String(chapter), chapter_title: chapterTitle,
    category, keywords: Array.isArray(keywords) ? keywords : String(keywords).split(' ').filter(Boolean)
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// SECTION A: IPC Sections 1-511 - every section with title + description
// (these are the sections not already in ipc.json or are expanded)
// ─────────────────────────────────────────────────────────────────────────────
const IPC_FULL = [
  // Chapter 1 - Preliminary
  ["1","Short title, extent and commencement","This Act shall be called the Indian Penal Code, and shall extend to the whole of India. It came into force on 1 May 1861. The Code applies to every person in India whether citizen or foreigner.","1","Preliminary","Criminal Law",["IPC S1 title extent India 1860 1861 citizen foreigner"]],
  ["2","Punishment of offences committed within India","Every person shall be liable to punishment under this Code for every act or omission contrary to the provisions thereof, of which he shall be guilty within India. Territorial application.","1","Preliminary","Criminal Law",["IPC S2 punishment India territory every person liability"]],
  ["3","Punishment of offences committed beyond India","Any person liable by any Indian law to be tried for an offence committed beyond India shall be dealt with according to this Code.","1","Preliminary","Criminal Law",["IPC S3 beyond India extraterritorial offence tried"]],
  ["4","Extension to extra-territorial offences","The provisions of this Code apply to any offence committed by any citizen of India in any place without and beyond India; or any person on any ship or aircraft registered in India.","1","Preliminary","Criminal Law",["IPC S4 extra-territorial citizen India ship aircraft registered"]],
  ["5","Certain laws not to be affected","Nothing in this Act shall affect the provisions of any Act for punishing mutiny and desertion of officers, soldiers, sailors or airmen in the service of the Government of India.","1","Preliminary","Criminal Law",["IPC S5 mutiny desertion soldiers sailors airmen special law"]],
  // Chapter 2 - General Explanations
  ["6","Definitions subject to exceptions","Throughout this Code every definition of an offence, every penal provision and every illustration thereof shall be understood subject to the exceptions contained in the Chapter entitled General Exceptions.","2","General Explanations","Criminal Law",["IPC S6 definitions penal provision illustrations general exceptions apply"]],
  ["7","Sense of expression once explained","Every expression which is explained in any part of this Code is used in every part of this Code in conformity with the explanation.","2","General Explanations","Criminal Law",["IPC S7 expression explained uniform conformity"]],
  ["8","Gender","The pronoun 'he' and its derivatives are used of any person whether male or female.","2","General Explanations","Criminal Law",["IPC S8 gender pronoun male female person"]],
  ["9","Number","Unless the contrary appears from the context, words importing the singular number include the plural number and vice versa.","2","General Explanations","Criminal Law",["IPC S9 number singular plural context"]],
  ["10","Man and Woman","'Man' denotes a male human being of any age. 'Woman' denotes a female human being of any age.","2","General Explanations","Criminal Law",["IPC S10 man woman male female human being any age"]],
  ["11","Person","The word 'person' includes any Company or Association or body of persons, whether incorporated or not.","2","General Explanations","Criminal Law",["IPC S11 person company association body incorporated not"]],
  ["12","Public","The word 'public' includes any class of the public or any community.","2","General Explanations","Criminal Law",["IPC S12 public class community"]],
  ["14","Servant of Government","The words 'servant of Government' denote any officer or servant continued, appointed or employed in India by or under the authority of Government.","2","General Explanations","Criminal Law",["IPC S14 servant government officer employed India authority"]],
  ["17","Government","The word 'Government' denotes the Central Government or the Government of a State.","2","General Explanations","Criminal Law",["IPC S17 government central state"]],
  ["19","Judge","The word 'Judge' denotes not only every person who is officially designated as a Judge, but also every person empowered by law to give a definitive judgment.","2","General Explanations","Criminal Law",["IPC S19 judge designation definitive judgment empowered law"]],
  ["20","Court of Justice","The words 'Court of Justice' denote a Judge who is empowered by law to act judicially alone, or a body of Judges empowered to act judicially as a body.","2","General Explanations","Criminal Law",["IPC S20 court justice judge body judicially"]],
  ["21","Public servant","The words 'public servant' denote a person falling under various categories including: every commissioned officer in the military, judicial officers, officers of courts, person entitled to receive fees or commission from government, arbitrators appointed by court, government employees.","2","General Explanations","Criminal Law",["IPC S21 public servant categories judicial military officer court government employee commissioned"]],
  ["22","Movable property","The words 'movable property' include corporeal property of every description, except land and things attached to the earth or permanently fastened to anything attached to the earth.","2","General Explanations","Criminal Law",["IPC S22 movable property corporeal description except land attached earth"]],
  ["23","Wrongful gain and wrongful loss","'Wrongful gain' is gain by unlawful means of property to which the person gaining is not legally entitled. 'Wrongful loss' is the loss by unlawful means of property to which the person losing it is legally entitled.","2","General Explanations","Criminal Law",["IPC S23 wrongful gain loss unlawful means property entitled legally"]],
  ["24","Dishonestly","Whoever does anything with the intention of causing wrongful gain to one person or wrongful loss to another person is said to do that thing 'dishonestly'.","2","General Explanations","Criminal Law",["IPC S24 dishonestly intention wrongful gain loss person"]],
  ["25","Fraudulently","A person is said to do a thing 'fraudulently' if he does that thing with intent to defraud but not otherwise.","2","General Explanations","Criminal Law",["IPC S25 fraudulently intent defraud"]],
  ["26","Reason to believe","A person is said to have 'reason to believe' a thing if he has sufficient cause to believe that thing but not otherwise.","2","General Explanations","Criminal Law",["IPC S26 reason to believe sufficient cause"]],
  ["28","Counterfeit","A person is said to 'counterfeit' who causes one thing to resemble another thing, intending by means of that resemblance to practice deception, or knowing it to be likely that deception will thereby be practiced.","2","General Explanations","Criminal Law",["IPC S28 counterfeit resemble deception practice intend"]],
  ["29","Document","The word 'document' denotes any matter expressed or described upon any substance by means of letters, figures or marks, or by more than one of those means, intended to be used as evidence of that matter.","2","General Explanations","Criminal Law",["IPC S29 document letters figures marks evidence substance expressed"]],
  ["34","Acts done by several persons in furtherance of common intention","When a criminal act is done by several persons in furtherance of the common intention of all, each of such persons is liable for that act in the same manner as if it were done by him alone. Rule of joint liability.","2","General Explanations","Criminal Law",["IPC S34 common intention several persons joint liability criminal act furtherance"]],
  ["35","When criminal act done with criminal knowledge","Whenever an act, which is criminal only by reason of its being done with a criminal knowledge or intention, is done by several persons, each who joins in the act with such knowledge or intention is liable.","2","General Explanations","Criminal Law",["IPC S35 criminal knowledge intention several persons join liable"]],
  ["37","Co-operation by doing one of several acts","When an offence is committed by means of several acts, whoever intentionally co-operates in the commission of that offence by doing any one of those acts, either singly or jointly, commits that offence.","2","General Explanations","Criminal Law",["IPC S37 co-operation several acts offence commission intentionally"]],
  ["38","Persons concerned in criminal act may be guilty of different offences","Where several persons are engaged in the commission of a criminal act, they may be guilty of different offences by means of that act.","2","General Explanations","Criminal Law",["IPC S38 several persons different offences engaged commission criminal act"]],
  ["39","Voluntarily","A person is said to cause an effect 'voluntarily' when he causes it by means whereby he intended to cause it, or by means which, at the time of employing those means, he knew or had reason to believe to be likely to cause it.","2","General Explanations","Criminal Law",["IPC S39 voluntarily cause effect intend knew reason believe"]],
  ["40","Offence","The word 'offence' denotes a thing made punishable by this Code. In Chapters V and VA, 'offence' has the meaning given to it by the IPC or any special law.","2","General Explanations","Criminal Law",["IPC S40 offence punishable code definition"]],
  ["44","Injury","The word 'injury' denotes any harm whatsoever illegally caused to any person, in body, mind, reputation or property.","2","General Explanations","Criminal Law",["IPC S44 injury harm illegally caused body mind reputation property"]],
  // Chapter 3 - Punishments
  ["53","Punishments","The punishments to which offenders are liable under the provisions of this Code are: First, Death; Secondly, Imprisonment for life; Thirdly, Imprisonment (rigorous or simple); Fourthly, Forfeiture of property; Fifthly, Fine. Sixth (under BNS 2023): Community service.","3","Punishments","Criminal Law",["IPC S53 punishments death life imprisonment rigorous simple forfeiture property fine BNS community service"]],
  ["54","Commutation of sentence of death","In every case in which sentence of death shall have been passed, the appropriate Government may, without the consent of the offender, commute the punishment for any other punishment provided by this Code.","3","Punishments","Criminal Law",["IPC S54 commutation death sentence government commute consent offender"]],
  ["55","Commutation of sentence of imprisonment for life","In every case in which sentence of imprisonment for life shall have been passed, the appropriate Government may commute the punishment for imprisonment of either description for a term not exceeding fourteen years.","3","Punishments","Criminal Law",["IPC S55 commutation life imprisonment fourteen years appropriate government"]],
  ["57","Fractions of terms of punishment","In calculating fractions of terms of punishment, imprisonment for life shall be reckoned as equivalent to imprisonment for twenty years.","3","Punishments","Criminal Law",["IPC S57 fractions terms punishment life imprisonment twenty years reckoned"]],
  ["60","Sentence rigorous or simple","In every case in which an offender is punishable with imprisonment which may be of either description, it shall be competent to the Court to direct in the sentence that such imprisonment shall be wholly rigorous, or wholly simple.","3","Punishments","Criminal Law",["IPC S60 rigorous simple sentence court direction either description"]],
  ["63","Amount of fine","Where no sum is expressed to which a fine may extend, the amount of fine to which the offender is liable is unlimited, but shall not be excessive.","3","Punishments","Criminal Law",["IPC S63 fine amount unlimited not excessive"]],
  ["64","Sentence of imprisonment for non-payment of fine","In every case of an offence punishable with fine only, in which the offender is sentenced to a fine, the court may award imprisonment in default of payment.","3","Punishments","Criminal Law",["IPC S64 imprisonment non-payment fine default award court sentence"]],
  ["71","Limit of punishment of offence made up of several offences","Where anything which is an offence is made up of parts, any of which parts is itself an offence, the offender shall not be punished with the punishment of more than one of such his offences.","3","Punishments","Criminal Law",["IPC S71 limit punishment offence parts punishment one offence"]],
  ["73","Solitary confinement","Whenever any person is convicted of an offence for which rigorous imprisonment is awarded, the Court may order that the offender be kept in solitary confinement for a portion not exceeding three months.","3","Punishments","Criminal Law",["IPC S73 solitary confinement rigorous imprisonment three months court order"]],
  ["75","Enhanced punishment for certain offences after previous conviction","Whoever, having been convicted by a Court in India, of an offence punishable under Chapter XII or XVII with imprisonment for three or more years, is again guilty of any such offence, is liable to imprisonment for life or ten years.","3","Punishments","Criminal Law",["IPC S75 enhanced punishment previous conviction Chapter XII XVII three years life ten years"]],
  // Chapter 4 - General Exceptions
  ["76","Act done by a person bound by law","Nothing is an offence which is done by a person who is, or who by reason of a mistake of fact believes himself to be, bound by law to do it. Example: a soldier obeying orders.","4","General Exceptions","Criminal Law",["IPC S76 bound by law mistake of fact defence soldier orders belief"]],
  ["77","Act of Judge when acting judicially","Nothing is an offence which is done by a Judge when acting judicially in the exercise of any power which is given to him by law.","4","General Exceptions","Criminal Law",["IPC S77 judge judicial power given law defence"]],
  ["78","Act done pursuant to judgment or order of Court","Nothing which is done in pursuance of, or which is warranted by the judgment or order of, a Court of Justice, if done whilst such judgment or order remains in force, is an offence.","4","General Exceptions","Criminal Law",["IPC S78 judgment court order pursuant warranted defence"]],
  ["79","Act justified by law or mistake of fact","Nothing is an offence which is done by any person who is justified by law, or who by reason of a mistake of fact believes himself to be justified by law, in doing it.","4","General Exceptions","Criminal Law",["IPC S79 justified by law mistake fact defence"]],
  ["80","Accident in doing a lawful act","Nothing is an offence which is done by accident or misfortune, and without any criminal intention or knowledge, in the doing of a lawful act in a lawful manner by lawful means and with proper care and caution.","4","General Exceptions","Criminal Law",["IPC S80 accident misfortune lawful act criminal intention knowledge caution"]],
  ["81","Act likely to cause harm but done without criminal intent to prevent other harm","Nothing is an offence merely because it is likely to cause harm, if it is done without any criminal intention to cause harm, and in good faith for the purpose of preventing or avoiding other harm.","4","General Exceptions","Criminal Law",["IPC S81 harm prevention good faith without criminal intention necessity"]],
  ["82","Act of child under seven years","Nothing is an offence which is done by a child under seven years of age. Children below 7 have absolute immunity - doli incapax.","4","General Exceptions","Criminal Law",["IPC S82 child under seven years absolute immunity doli incapax offence"]],
  ["83","Act of child above seven under twelve of immature understanding","Nothing is an offence which is done by a child above seven years of age and under twelve, who has not attained sufficient maturity of understanding to judge the nature and consequences of his conduct.","4","General Exceptions","Criminal Law",["IPC S83 child seven twelve years maturity understanding consequences doli incapax partial"]],
  ["84","Act of person of unsound mind","Nothing is an offence which is done by a person who, at the time of doing it, by reason of unsoundness of mind, is incapable of knowing the nature of the act, or that he is doing what is either wrong or contrary to law. M'Naghten test.","4","General Exceptions","Criminal Law",["IPC S84 unsound mind insanity M'Naghten incapable knowing nature wrong contrary law defence"]],
  ["85","Act of person incapable of judgment due to intoxication against his will","Nothing is an offence which is done by a person who, at the time of doing it, is incapable of knowing the nature of the act by reason of intoxication, provided that the intoxication was administered to him without his knowledge or against his will.","4","General Exceptions","Criminal Law",["IPC S85 intoxication against will without knowledge defence incapable knowing involuntary"]],
  ["86","Offence requiring knowledge committed by intoxicated person","In cases where an act done is not an offence unless done with particular knowledge or intent, a person who does the act in a state of intoxication shall be liable to be dealt with as if he had the same knowledge as he would have had if he had not been intoxicated - unless the intoxication was involuntary.","4","General Exceptions","Criminal Law",["IPC S86 intoxication knowledge intent voluntary offence liable treated sober knowledge"]],
  ["87","Act not known likely to cause death or grievous hurt done by consent","Nothing which is not intended to cause death, or grievous hurt, and which is not known to be likely to cause death or grievous hurt, is an offence by reason of any harm which it may cause to any person above 18 years who has given consent.","4","General Exceptions","Criminal Law",["IPC S87 consent above eighteen harm not death grievous hurt defence"]],
  ["88","Act not intended to cause death done in good faith for person's benefit with consent","Nothing, which is not intended to cause death, is an offence by reason of any harm which it may cause, or be intended by the doer to cause, to any person for whose benefit it is done in good faith, and who has given consent.","4","General Exceptions","Criminal Law",["IPC S88 good faith benefit consent not death harm medical treatment defence"]],
  ["89","Act done in good faith for benefit of child or insane person by guardian","Nothing done in good faith for the benefit of a person under 12 years of age, or of unsound mind, by their guardian, is an offence.","4","General Exceptions","Criminal Law",["IPC S89 guardian good faith child under twelve unsound mind benefit defence"]],
  ["90","Consent given under fear or misconception","A consent is not such a consent as is intended by any section of this Code, if the consent is given by a person under fear of injury, or under a misconception of fact, or if the consenting person is of unsound mind, intoxicated, or under twelve years of age.","4","General Exceptions","Criminal Law",["IPC S90 consent fear injury misconception fact unsound mind intoxicated twelve years vitiated"]],
  ["91","Exclusion of acts which are offences independently of harm caused","The exceptions in sections 87, 88 and 89 do not extend to acts which are offences independently of any harm which they may cause to the person giving consent.","4","General Exceptions","Criminal Law",["IPC S91 exclusion S87 S88 S89 offence independently harm consent"]],
  ["92","Act done in good faith for benefit of person without consent when impossible to obtain","Nothing is an offence by reason of any harm it may cause to a person for whose benefit it is done in good faith, even without consent, if circumstances are such that consent cannot be obtained or the person is incapable of giving consent.","4","General Exceptions","Criminal Law",["IPC S92 good faith benefit no consent impossible incapable emergency"]],
  ["93","Communication made in good faith","No communication made in good faith is an offence by reason of any harm to the person to whom it is made, if it is made for the benefit of that person.","4","General Exceptions","Criminal Law",["IPC S93 communication good faith benefit harm not offence"]],
  ["94","Act to which a person is compelled by threats - Duress","Except murder, and offences against the State punishable with death, nothing is an offence which is done by a person who is compelled to do it by threats, which at the time of doing it, reasonably cause the apprehension that instant death will otherwise be the consequence. Duress defence.","4","General Exceptions","Criminal Law",["IPC S94 compelled threats duress instant death apprehension exception murder state offence"]],
  ["95","Act causing slight harm","Nothing is an offence by reason that it causes, or that it is intended to cause, or that it is known to be likely to cause, any harm, if that harm is so slight that no person of ordinary sense and temper would complain of such harm. De minimis defence.","4","General Exceptions","Criminal Law",["IPC S95 slight harm de minimis ordinary sense temper not offence"]],
  ["96","Things done in private defence","Nothing is an offence which is done in the exercise of the right of private defence.","4","General Exceptions","Criminal Law",["IPC S96 private defence right nothing offence exercise"]],
  ["97","Right of private defence of body and property","Every person has a right, subject to restrictions in section 99, to defend his own body, and the body of any other person, against any offence affecting the human body; and the property, whether movable or immovable, of himself or of any other person, against theft, robbery, mischief or criminal trespass.","4","General Exceptions","Criminal Law",["IPC S97 private defence body property person theft robbery mischief trespass right section 99"]],
  ["98","Right of private defence against person of unsound mind etc.","When an act which would otherwise be a certain offence is not that offence by reason of the youth, want of maturity, unsoundness of mind, or intoxication of the person doing that act, every person has the same right of private defence against that act.","4","General Exceptions","Criminal Law",["IPC S98 private defence unsound mind youth intoxication same right"]],
  ["99","Acts against which there is no right of private defence","There is no right of private defence against an act which does not reasonably cause the apprehension of death or of grievous hurt, if done by a public servant acting in good faith under colour of his office. Also limited by recourse to public authority.","4","General Exceptions","Criminal Law",["IPC S99 no private defence public servant good faith colour office recourse public authority limitations"]],
  ["100","When right of private defence of body extends to causing death","The right of private defence of the body extends to voluntary causing of death or any other harm to the assailant in six specified circumstances: assault causing reasonable apprehension of death; grievous hurt; rape; unnatural lust; kidnapping or abduction; wrongful confinement.","4","General Exceptions","Criminal Law",["IPC S100 private defence body death six circumstances rape kidnapping grievous hurt confinement assault apprehension"]],
  ["101","When right of private defence extends to causing harm other than death","If the offence causing exercise of the right is not within S.100, the right does not extend to causing death but does extend to causing any harm other than death.","4","General Exceptions","Criminal Law",["IPC S101 private defence harm other than death not S100 offence"]],
  ["102","Commencement and continuance of right of private defence of body","The right commences as soon as a reasonable apprehension of danger to the body arises from an attempt or threat to commit an offence though the offence may not have been committed; and continues as long as such apprehension continues.","4","General Exceptions","Criminal Law",["IPC S102 private defence commencement continuance apprehension danger attempt threat"]],
  ["103","When right of private defence of property extends to causing death","The right of private defence of property extends to causing death or any other harm against: robbery; housebreaking by night; mischief by fire in a building/vessel; theft with aggravation; wrongful confinement of person.","4","General Exceptions","Criminal Law",["IPC S103 property private defence death robbery housebreaking night fire mischief theft aggravation wrongful confinement"]],
  ["104","When right of private defence of property extends to harm other than death","If the offence causing exercise of right of private defence of property be theft, mischief or criminal trespass, not of the descriptions in S.103, the right does not extend to causing death but does extend to any harm.","4","General Exceptions","Criminal Law",["IPC S104 property private defence harm not death theft mischief trespass"]],
  ["105","Commencement and continuance of right of private defence of property","The right of private defence of property commences when a reasonable apprehension of danger to the property commences. Continues: for theft - until offender has effected retreat with property; for robbery - while continues; for criminal trespass - as long as continues.","4","General Exceptions","Criminal Law",["IPC S105 property private defence commencement apprehension theft robbery trespass continues"]],
  ["106","Right of private defence against deadly assault when innocent person at risk","If in exercise of the right of private defence against an assault which reasonably causes the apprehension of death, the defender cannot effectively exercise that right without risk of harm to an innocent person, his right extends to the running of that risk.","4","General Exceptions","Criminal Law",["IPC S106 private defence deadly assault innocent person risk apprehension death extends"]],
];

IPC_FULL.forEach(([sec,title,desc,ch,cht,cat,kw])=>
  add("Indian Penal Code, 1860","IPC",sec,title,desc,ch,cht,cat,kw));

// ─────────────────────────────────────────────────────────────────────────────
// SECTION B: Negotiable Instruments Act 1881 - full detailed sections
// ─────────────────────────────────────────────────────────────────────────────
const NIA_FULL = [
  ["4","Promissory note defined","A promissory note is an instrument in writing (not being a bank-note or a currency-note) containing an unconditional undertaking, signed by the maker, to pay a certain sum of money only to, or to the order of, a certain person, or to the bearer of the instrument.","1","Preliminary","Commercial Law / NI",["NIA S4 promissory note unconditional undertaking signed maker pay certain sum bearer"]],
  ["5","Bill of exchange defined","A bill of exchange is an instrument in writing containing an unconditional order, signed by the maker, directing a certain person to pay a certain sum of money only to, or to the order of, a certain person or to the bearer of the instrument.","1","Preliminary","Commercial Law / NI",["NIA S5 bill of exchange unconditional order signed maker directing certain person sum bearer"]],
  ["6","Cheque defined","A cheque is a bill of exchange drawn on a specified banker and not expressed to be payable otherwise than on demand. A cheque also includes the electronic image of a truncated cheque and a cheque in the electronic form.","1","Preliminary","Commercial Law / NI",["NIA S6 cheque bill of exchange banker demand electronic image truncated form"]],
  ["7","Drawer, drawee etc.","The maker of a bill of exchange or cheque is called the 'drawer'. The person thereby directed to pay is called the 'drawee'. The person named in the instrument to whom or to whose order the money is by the instrument directed to be paid is called the 'payee'.","1","Preliminary","Commercial Law / NI",["NIA S7 drawer drawee payee maker directed pay named instrument"]],
  ["8","Holder","The 'holder' of a promissory note, bill of exchange or cheque means any person entitled in his own name to the possession thereof and to receive or recover the amount due thereon from the parties thereto.","1","Preliminary","Commercial Law / NI",["NIA S8 holder entitled own name possession amount due parties"]],
  ["9","Holder in due course","Holder in due course means any person who for consideration became the possessor of a promissory note, bill of exchange or cheque if payable to bearer, or the payee or indorsee thereof, before the amount mentioned in it became payable, and without having sufficient cause to believe that any defect existed in the title of the person from whom he derived his title.","1","Preliminary","Commercial Law / NI",["NIA S9 holder in due course consideration possessor before maturity no knowledge defect title good faith"]],
  ["10","Payment in due course","Payment in due course means payment in accordance with the apparent tenor of the instrument in good faith and without negligence to any person in possession thereof under circumstances which do not afford a reasonable ground for believing that he is not entitled to receive such payment.","1","Preliminary","Commercial Law / NI",["NIA S10 payment due course tenor good faith negligence possession entitled receive"]],
  ["14","Negotiable instrument","A promissory note, bill of exchange or cheque is payable to order which is expressed to be so payable or which is expressed to be payable to a particular person, and does not contain words prohibiting transfer or indicating an intention that it shall not be transferable.","2","Negotiability","Commercial Law / NI",["NIA S14 negotiable instrument payable order transfer prohibit"]],
  ["15","Indorsement","When the maker or holder of a negotiable instrument signs the same, otherwise than as such maker, for the purpose of negotiation, on the back or face thereof or on a slip of paper annexed thereto, he is said to indorse the same, and is called the 'indorser'.","2","Negotiability","Commercial Law / NI",["NIA S15 indorsement holder signs back face slip paper annexed negotiation indorser"]],
  ["16","Indorsement in blank and in full","If the indorser signs his name only, the indorsement is called an indorsement in blank, and if he also adds a direction to pay to a specified person, or his order, the indorsement is said to be in full, and the person whose name is specified is called the 'indorsee'.","2","Negotiability","Commercial Law / NI",["NIA S16 indorsement blank full signs name direction pay specified indorsee"]],
  ["17","Ambiguous instruments","Where an instrument may be construed either as a promissory note or bill of exchange, the holder may at his election treat it as either, and the instrument shall be thenceforward treated accordingly.","2","Negotiability","Commercial Law / NI",["NIA S17 ambiguous instrument promissory note bill of exchange holder election treat"]],
  ["19","Instruments payable on demand","A promissory note or bill of exchange, in which no time for payment is specified, and a cheque, are payable on demand.","2","Negotiability","Commercial Law / NI",["NIA S19 payable on demand no time specified cheque promissory note bill of exchange"]],
  ["20","Inchoate stamped instruments","Where one person signs and delivers to another a paper stamped in accordance with the law relating to negotiable instruments then in force in India, and either wholly blank or having written thereon an incomplete negotiable instrument, he thereby gives prima facie authority to the holder thereof to make or complete as the case may be upon it a negotiable instrument.","2","Negotiability","Commercial Law / NI",["NIA S20 inchoate stamped blank incomplete authority holder complete prima facie"]],
  ["22","Maturity","The maturity of a promissory note or bill of exchange is the date at which it falls due. Days of grace - every promissory note or bill of exchange which is not expressed to be payable on demand, at sight or on presentment is at maturity on the third day after the day on which it is expressed to be payable.","2","Maturity","Commercial Law / NI",["NIA S22 maturity date due days of grace three days promissory note bill of exchange"]],
  ["25","When presentment unnecessary","Presentment for payment is not required in order to charge any person liable on a negotiable instrument - where, after the instrument becomes due, the person liable consents to pay; where the instrument is accepted or made payable at a particular place, and the maker, drawee or acceptor is not there on the due date.","3","Presentment","Commercial Law / NI",["NIA S25 presentment unnecessary consent due charge liable instrument place"]],
  ["31","Liability of drawer","The drawer of a bill of exchange or cheque is bound, in case of dishonour by the drawee or acceptor thereof, to compensate the holder, provided due notice of dishonour has been given to or received by the drawer.","4","Parties to Instruments","Commercial Law / NI",["NIA S31 liability drawer dishonour compensate holder notice due"]],
  ["32","Liability of indorser","In the absence of a contract to the contrary, whoever indorses and delivers a negotiable instrument before maturity, without, in such indorsement, expressly excluding his own liability, engages that on due presentment it shall be accepted and paid according to its tenor.","4","Parties to Instruments","Commercial Law / NI",["NIA S32 liability indorser maturity excludes engages accepted paid tenor presentment"]],
  ["36","Liability of prior parties to holder in due course","Every prior party to a negotiable instrument is liable thereon to a holder in due course until the instrument is duly satisfied.","4","Parties to Instruments","Commercial Law / NI",["NIA S36 prior parties liability holder in due course satisfied instrument"]],
  ["43","Negotiable instrument made etc. without consideration","A negotiable instrument made, drawn, accepted, indorsed or transferred without consideration, or for a consideration which fails, creates no obligation of payment between the parties to the transaction.","4","Consideration","Commercial Law / NI",["NIA S43 no consideration without obligation payment parties negotiable instrument fails"]],
  ["56","Presentment for acceptance - time","Bills of exchange payable after sight must be presented for acceptance, or negotiated, within a reasonable time. If not presented within a reasonable time, all drawers and indorsers who acquired their title after the lapse of this time are discharged.","3","Presentment","Commercial Law / NI",["NIA S56 presentment acceptance after sight reasonable time drawers indorsers discharged"]],
  ["64","Presentment for payment","A promissory note or bill of exchange must be presented for payment to the maker, acceptor or drawee thereof respectively, by or on behalf of the holder, as hereinafter provided. Holder loses right of recourse against prior parties if presentment not made.","3","Presentment","Commercial Law / NI",["NIA S64 presentment payment maker acceptor drawee holder right recourse prior parties"]],
  ["85","Cheque payable to order - bank's protection","Where a cheque payable to order purports to be indorsed by or on behalf of the payee, the drawee is discharged by payment in due course. Protection to drawee banker.","5","Instruments Crossed","Commercial Law / NI",["NIA S85 cheque payable order indorsed payee drawee discharged payment due course bank protection"]],
  ["85A","Crossed cheques - protection to banker","Where the drawee of a cheque pays it in good faith and without negligence (a) and the cheque bears a crossing, he is not responsible to the true owner of the cheque if the payment is in due course and the crossing has been complied with.","5","Instruments Crossed","Commercial Law / NI",["NIA S85A crossed cheque banker good faith negligence true owner protection"]],
  ["89","Payment on crossed cheque","Where a cheque is paid in due course, the banker paying the cheque does not incur any liability to the true owner of the cheque only by reason of payment being irregular.","5","Instruments Crossed","Commercial Law / NI",["NIA S89 payment crossed cheque banker due course no liability true owner"]],
  ["91","Dishonour by non-acceptance","A bill of exchange is said to be dishonoured by non-acceptance when the drawee, or one of several drawees not being partners, makes default in acceptance upon being duly required to accept the bill, or when presentment is excused and the bill is not accepted.","6","Dishonour","Commercial Law / NI",["NIA S91 dishonour non-acceptance drawee partners default acceptance excused presentment"]],
  ["92","Dishonour by non-payment","A promissory note, bill of exchange or cheque is said to be dishonoured by non-payment when the maker of the note, acceptor of the bill or drawee of the cheque makes default in payment upon being duly required to pay the same.","6","Dishonour","Commercial Law / NI",["NIA S92 dishonour non-payment maker acceptor drawee default payment"]],
  ["93","Notice of dishonour","When a promissory note, bill of exchange or cheque is dishonoured by non-acceptance or non-payment, the holder must give notice of dishonour to all parties whom the holder seeks to make liable on the instrument.","6","Notice of Dishonour","Commercial Law / NI",["NIA S93 notice dishonour holder parties liable instrument non-acceptance non-payment"]],
  ["98","When notice of dishonour unnecessary","Notice of dishonour is not necessary when: the party entitled to receive notice cannot, after due search, be found; the dishonour was caused by acts or omissions of the party to whom notice should be given; there is a waiver of notice; the instrument is not available to give notice.","6","Notice of Dishonour","Commercial Law / NI",["NIA S98 notice dishonour unnecessary cannot found waiver omission acts not available"]],
  ["99","Noting","When a promissory note or bill of exchange has been dishonoured by non-acceptance or non-payment, the holder may cause such dishonour to be noted by a notary public upon the instrument, or upon a paper attached thereto.","6","Noting and Protest","Commercial Law / NI",["NIA S99 noting notary public dishonour non-acceptance payment instrument paper attached"]],
  ["100","Protest","When a promissory note or bill of exchange has been dishonoured by non-acceptance or non-payment, any holder may, within a reasonable time, cause such dishonour to be noted and certified by a notary public. Such certificate is called a protest.","6","Noting and Protest","Commercial Law / NI",["NIA S100 protest certificate notary public dishonour non-acceptance payment holder reasonable time"]],
  ["108","Acceptance of bill of exchange by several drawees","If a bill of exchange is addressed to two or more drawees who are not partners, acceptance by one of them does not bind the others.","4","Parties to Instruments","Commercial Law / NI",["NIA S108 acceptance several drawees partners one bind others"]],
  ["118","Presumptions as to negotiable instruments","Until the contrary is proved, the following presumptions shall be made: every negotiable instrument was made or drawn for consideration; every such instrument bearing a date was made or drawn on such date; every accepted bill was accepted within a reasonable time after its date; every transfer of such instrument was made before maturity.","7","Rules of Evidence","Commercial Law / NI",["NIA S118 presumptions every negotiable instrument consideration date accepted transfer maturity"]],
  ["119","Presumption on proof of protest","In a suit upon an instrument which has been dishonoured, the court shall, on proof of protest, presume the fact of dishonour, unless and until such fact is disproved.","7","Rules of Evidence","Commercial Law / NI",["NIA S119 presumption proof protest dishonour court fact disproved"]],
  ["120","Estoppel against denying original validity","No maker of a promissory note, and no drawer of a bill of exchange or cheque, and no acceptor of a bill for the honour of the drawer shall, in a suit thereon by a holder in due course, be permitted to deny the validity of the instrument as originally made or drawn.","7","Rules of Evidence","Commercial Law / NI",["NIA S120 estoppel deny validity maker drawer acceptor holder due course original"]],
  ["123","Cheques crossed generally","Where a cheque bears across its face an addition of the words 'and company' or any abbreviation thereof, between two parallel transverse lines, either with or without the words 'not negotiable', that addition shall be deemed a crossing, and the cheque shall be deemed to be crossed generally.","5","Instruments Crossed","Commercial Law / NI",["NIA S123 cheque crossed generally two parallel lines and company not negotiable"]],
  ["124","Cheques crossed specially","Where a cheque bears across its face an addition of the name of a banker, either with or without the words 'not negotiable', that addition shall be deemed a crossing, and the cheque shall be deemed to be crossed specially and to be crossed to that banker.","5","Instruments Crossed","Commercial Law / NI",["NIA S124 cheque crossed specially name banker not negotiable addition"]],
  ["125","Crossing after issue","Where a cheque is uncrossed, the holder may cross it generally or specially. Where it is crossed generally, the holder may cross it specially. Where it is crossed generally or specially, the holder may add the words 'not negotiable'.","5","Instruments Crossed","Commercial Law / NI",["NIA S125 crossing after issue holder generally specially not negotiable add"]],
  ["126","Payment of cheque crossed generally","Where a cheque is crossed generally, the banker on whom it is drawn shall not pay it otherwise than to a banker.","5","Instruments Crossed","Commercial Law / NI",["NIA S126 payment crossed generally banker drawn pay only to banker"]],
  ["127","Payment of cheque crossed specially","Where a cheque is crossed specially, the banker on whom it is drawn shall not pay it otherwise than to the banker to whom it is crossed, or his agent for collection being a banker.","5","Instruments Crossed","Commercial Law / NI",["NIA S127 payment crossed specially banker pay only to specified banker agent collection"]],
  ["129","Banker paying crossed cheque protected","Where a banker in good faith and without negligence pays a crossed cheque, he shall not incur any liability by reason only of the payment being made otherwise than in accordance with the crossing.","5","Instruments Crossed","Commercial Law / NI",["NIA S129 banker good faith negligence crossed cheque no liability payment protection"]],
  ["130","Cheque bearing not negotiable crossing","A person taking a cheque crossed generally or specially, bearing in either case the words 'not negotiable' shall not have, and shall not be capable of giving, a better title to the cheque than that which the person from whom he took it had.","5","Instruments Crossed","Commercial Law / NI",["NIA S130 not negotiable crossing title holder not better than transferor protection"]],
  ["131","Non-liability of banker receiving payment of cheque","A banker who has in good faith and without negligence received payment for a customer of a cheque crossed generally or specially to himself, shall not, in case the title to the cheque proves defective, incur any liability to the true owner merely by reason of having received such payment.","5","Instruments Crossed","Commercial Law / NI",["NIA S131 banker good faith negligence received payment defective title no liability customer protection collecting bank"]],
  ["132","Cheques - electronic clearing system","Where any cheque is presented for payment by electronic means by an institution or organisation empowered to make use of electronic or other means, the bank of the drawee shall be liable only if the payment is made in accordance with S.10 and not otherwise.","5","Instruments Crossed","Commercial Law / NI",["NIA S132 electronic clearing system cheque institution bank drawee payment S10"]],
  ["133","Cheque truncation - S.6 Explanation 2","Truncated cheque means a cheque which is truncated during the course of a clearing cycle, whether by the clearing house or by the bank whether paying or receiving payment, immediately on generation of an electronic image for transmission, substituting the further physical movement of the cheque in writing.","5","Instruments Crossed","Commercial Law / NI",["NIA truncated cheque electronic image clearing cycle bank paying receiving substituting physical movement"]],
  ["138","Dishonour of cheque - ingredients","For Section 138 NIA to apply: (1) The cheque must be drawn for legally enforceable debt or liability. (2) Cheque must be presented within its validity period (3 months). (3) Cheque must be returned unpaid by bank due to insufficient funds or exceeding arrangement. (4) Payee must serve demand notice within 30 days of dishonour. (5) Drawer must fail to pay within 15 days of receipt of notice. (6) Complaint must be filed within 30 days of expiry of notice period.","17","Cheque Bounce","Commercial Law / NI",["NIA S138 dishonour cheque ingredients legally enforceable debt three months notice 30 days 15 days complaint 30 days"]],
  ["140","Defence which may not be allowed in any prosecution under S.138","It shall not be a defence in a prosecution for an offence under section 138 that the drawer had no reason to believe when he issued the cheque that the cheque may be dishonoured on presentment for the reasons stated in that section.","17","Cheque Bounce","Commercial Law / NI",["NIA S140 defence not allowed S138 no reason believe dishonoured prosecution"]],
  ["141","Offences by companies","If the person committing an offence under section 138 is a company, every person who, at the time the offence was committed, was in charge of, and was responsible to, the company for the conduct of its business, shall be deemed to be guilty of the offence.","17","Cheque Bounce","Commercial Law / NI",["NIA S141 company offence director responsible charged guilty S138"]],
  ["142","Cognizance of offences","Notwithstanding anything contained in the Code of Criminal Procedure: no court shall take cognizance of any offence punishable under section 138 except upon a complaint, in writing, made by the payee or the holder in due course of the cheque as the case may be; and such complaint is made within one month of the date on which the cause of action arises under clause (c) of the proviso to section 138.","17","Cheque Bounce","Commercial Law / NI",["NIA S142 cognizance complaint writing payee holder in due course one month cause of action"]],
  ["142A","Validation of transfer of pending cases","Notwithstanding anything contained in this Act or the Code of Criminal Procedure, 1973, every complaint under section 142 shall be inquired into and tried only by a court in whose local jurisdiction the bank branch of the payee is situated. This 2015 amendment clarified jurisdiction for cheque bounce cases.","17","Cheque Bounce","Commercial Law / NI",["NIA S142A jurisdiction cheque bounce payee bank branch 2015 amendment court local"]],
  ["143","Power of court to try cases summarily","Notwithstanding anything contained in the Code of Criminal Procedure, 1973, all offences under Chapter XVII shall be tried by a Judicial Magistrate of the First Class or by a Metropolitan Magistrate and the provisions of sections 262 to 265 of CrPC shall, as far as possible, apply to such trials. The period of imprisonment on summary conviction shall not exceed one year.","17","Cheque Bounce","Commercial Law / NI",["NIA S143 summary trial JMFC Metropolitan Magistrate Chapter XVII one year imprisonment summary conviction"]],
  ["143A","Power to direct interim compensation","The Court trying an offence under section 138 may order the drawer of the cheque to pay interim compensation to the complainant - not exceeding 20% of cheque amount. To be paid within 60 days. On acquittal, drawer entitled to repayment.","17","Cheque Bounce","Commercial Law / NI",["NIA S143A interim compensation 20 percent cheque amount 60 days acquittal repayment 2018 amendment"]],
  ["144","Mode of service of summons","Despite section 62 of Code of Criminal Procedure, in addition to and not in derogation of service by post, service of summons by speed post or courier services by the court issuing such summons is deemed to have been effected if the summons was addressed to the drawer at the address given by him in the cheque.","17","Cheque Bounce","Commercial Law / NI",["NIA S144 summons service post speed post courier drawer address cheque"]],
  ["147","Offences to be compoundable","Notwithstanding anything contained in the Code of Criminal Procedure, every offence punishable under this Act shall be compoundable. Cheque bounce cases can be compounded at any stage.","17","Cheque Bounce","Commercial Law / NI",["NIA S147 compoundable offence cheque bounce any stage CrPC"]],
  ["148","Power of Appellate Court to order payment pending appeal","Notwithstanding anything contained in the Code of Criminal Procedure, in an appeal by the drawer against conviction under section 138, the Appellate Court may order the appellant to deposit such sum which shall be a minimum of 20% of the fine or compensation awarded by the trial court.","17","Cheque Bounce","Commercial Law / NI",["NIA S148 appeal drawer conviction 20 percent fine compensation deposit Appellate Court CrPC"]],
];
NIA_FULL.forEach(([sec,title,desc,ch,cht,cat,kw])=>
  add("Negotiable Instruments Act, 1881","NIA",sec,title,desc,ch,cht,cat,kw));

// ─────────────────────────────────────────────────────────────────────────────
// SECTION C: Motor Vehicles Act 1988 - key sections with details
// ─────────────────────────────────────────────────────────────────────────────
const MVA_DETAILED = [
  ["3","Necessity for driving licence","No person shall drive a motor vehicle in any public place unless he holds an effective driving licence issued to him authorising him to drive the vehicle. A learner's licence is valid for 6 months. Driving without licence: S.181 MVA - imprisonment up to 3 months or fine Rs 5,000 or both (2019 amendment).","2","Licensing","Motor Vehicles Law",["MVA S3 driving licence effective public place learner 6 months S181 3 months Rs 5000 2019"]],
  ["4","Age limit in connection with driving","No person under the age of eighteen years shall drive a motor vehicle in any public place. Minor driving: S.199A - parent/guardian liable, motor vehicle registration cancelled.","2","Licensing","Motor Vehicles Law",["MVA S4 age eighteen years minor public place S199A parent guardian registration cancelled"]],
  ["5","Responsibility of owners of motor vehicles for contravention of sections 3 and 4","No owner or person in charge of a motor vehicle shall cause or permit any person who does not satisfy the requirements of section 3 or section 4 to drive the vehicle.","2","Licensing","Motor Vehicles Law",["MVA S5 owner permit unlicensed under-age drive responsibility section 3 4"]],
  ["8","Grant of learner's licence","Any person who is not disqualified under section 7 and who wants to drive a motor vehicle of any specified class or description may apply to the licensing authority having jurisdiction in the area for a learner's licence.","2","Licensing","Motor Vehicles Law",["MVA S8 learner licence application licensing authority class description disqualification"]],
  ["9","Grant of driving licences","Any person who is not disqualified under section 7 and who is not less than twenty years of age in the case of transport vehicle, and eighteen years for other vehicles, may apply to the licensing authority for a driving licence.","2","Licensing","Motor Vehicles Law",["MVA S9 driving licence twenty years transport vehicle eighteen other application"]],
  ["10","Form and contents of driving licences","Every licence authorising the driving of a transport vehicle shall be in Form 5 and every other licence shall be in Form 4 as prescribed. A licence shall specify the classes of vehicles for which it is valid and shall bear photograph of licence holder.","2","Licensing","Motor Vehicles Law",["MVA S10 form driving licence Form 4 Form 5 transport vehicle classes photograph"]],
  ["19","Disqualification for holding or obtaining driving licence","A court convicting a person for any offence under this Act or any other law if it considers necessary, having regard to the nature of offence, may pass an order disqualifying the convicted person for holding or obtaining a driving licence for such period as it thinks fit.","2","Licensing","Motor Vehicles Law",["MVA S19 disqualification convicted person driving licence court order offence period"]],
  ["22","Registration of motor vehicles","No person shall drive any motor vehicle and no owner shall cause or permit a motor vehicle to be driven in any public place unless the vehicle is registered in accordance with this Chapter.","3","Registration","Motor Vehicles Law",["MVA S22 registration motor vehicle public place requirement chapter owner permit"]],
  ["39","Necessity for insurance against third party risk","No person shall use, except as a passenger, or cause or allow any other person to use, a motor vehicle in a public place, unless there is in force in relation to the use of the vehicle by that person or that other person, as the case may be, a policy of insurance complying with the requirements of Chapter XI.","11","Insurance","Motor Vehicles Law",["MVA S39 insurance third party risk public place Chapter XI policy use allow cause"]],
  ["49","Change of residence or place of business","Within thirty days of the change, the owner of a motor vehicle shall report the change of his address to the registering authority within whose jurisdiction he has his new address.","3","Registration","Motor Vehicles Law",["MVA S49 change residence address thirty days registering authority owner motor vehicle"]],
  ["56","Certificate of fitness of transport vehicles","A transport vehicle shall not be deemed to be validly registered for the purposes of section 39 unless it carries a certificate of fitness in the prescribed form, issued by the prescribed authority, to the effect that the vehicle complies with all the requirements of the Act.","3","Registration","Motor Vehicles Law",["MVA S56 certificate fitness transport vehicle registered form authority requirements comply"]],
  ["63","Necessity for permit","No owner of a motor vehicle shall use or permit the use of the vehicle as a transport vehicle in any public place whether or not such vehicle is actually carrying any passengers or goods save in accordance with the conditions of a permit granted or countersigned by a Regional or State Transport Authority.","4","Permits","Motor Vehicles Law",["MVA S63 permit transport vehicle public place Regional State Transport Authority conditions"]],
  ["112","Speeding - limits","No person shall drive a motor vehicle or cause or allow a motor vehicle to be driven in any public place at a speed exceeding the maximum speed or below the minimum speed fixed for the vehicle or for that class or type of vehicle or for that road or class of road, under the Act.","12","Traffic Rules","Motor Vehicles Law",["MVA S112 speed limit maximum minimum vehicle type road class public place"]],
  ["122","Drunken driving","Whoever, while driving or attempting to drive a motor vehicle, has, in his blood, alcohol exceeding 30 mg per 100 ml of blood detected in a test by a breath analyser, shall be punishable for a first offence with imprisonment for a term which may extend to six months, or with fine up to ten thousand rupees, or with both.","12","Traffic Rules","Motor Vehicles Law",["MVA S122 drunken driving blood alcohol 30 mg breath analyser first offence six months ten thousand rupees"]],
  ["129","Wearing of protective headgear - helmet","Every person driving or riding (otherwise than in a sidecar) on a motor cycle of any class shall wear protective headgear conforming to prescribed standards. S.194D: fine Rs 1,000, disqualification from holding driving licence for 3 months. BIS standard helmet required.","12","Traffic Rules","Motor Vehicles Law",["MVA S129 helmet motor cycle protective headgear prescribed standards S194D Rs 1000 3 months BIS"]],
  ["134","Driver to stop in case of accident","The driver of a motor vehicle involved in an accident shall stop the vehicle at the scene of the accident, take all reasonable steps to secure medical attention for the injured person, report to nearest police station, and disclose information of insurance.","12","Traffic Rules","Motor Vehicles Law",["MVA S134 accident stop medical attend police report insurance disclose driver"]],
  ["140","Liability without fault in certain cases","In any claim for compensation in respect of the death of, or permanent disablement to, any person resulting from an accident arising out of the use of a motor vehicle or motor vehicles, the claimant shall be entitled to compensation even if he is unable to prove wrongful act, neglect, or default on the part of any person.","11","Insurance / Compensation","Motor Vehicles Law",["MVA S140 no fault liability compensation death permanent disability accident motor vehicle without proof wrongful act"]],
  ["149","Duty of insurers to satisfy judgments","Where a certificate of insurance has been issued to the insured in respect of the use of the vehicle in a public place, the insurer is directly liable to satisfy the judgment obtained by the third party claimant in a suit against the person insured.","11","Insurance","Motor Vehicles Law",["MVA S149 insurer directly liable judgment third party certificate public place insured suit"]],
  ["158","Duty to furnish particulars of vehicle involved in accident","When any accident occurs in which a motor vehicle is involved, the driver of the vehicle shall, on demand, furnish his name, address, registration number of vehicle, particulars of insurance, driving licence number to any person affected.","12","Traffic Rules","Motor Vehicles Law",["MVA S158 accident particulars name address registration insurance driving licence demand person affected"]],
  ["159","Duty to report accidents and furnish information regarding insurance","The driver of a motor vehicle involved in any accident resulting in the death of, or bodily injury to, any person shall report the accident and comply with the requirements imposed by section 134.","12","Traffic Rules","Motor Vehicles Law",["MVA S159 duty report accident death injury section 134 comply requirements"]],
  ["163A","Special provisions as to payment of compensation on structured basis","Notwithstanding anything contained in this Act or in any other law for the time being in force or instrument having the force of law, the owner of the motor vehicle or the authorised insurer shall be liable to pay in the case of death or permanent disablement due to accident arising out of the use of motor vehicle, compensation based on the age and annual income of the person as per Schedule II.","11","Insurance / Compensation","Motor Vehicles Law",["MVA S163A structured compensation Schedule II age income death permanent disablement no fault]"]],
  ["166","Application for compensation","An application for compensation arising out of an accident of the nature specified in sub-section (1) of section 165 may be made by the person who has sustained the injury; or by the owner of the property; or where death has resulted from the accident, by all or any of the legal representatives of the deceased.","11","Insurance / Compensation","Motor Vehicles Law",["MVA S166 compensation application MACT injured owner property death legal representatives"]],
  ["168","Award of the Claims Tribunal","On receipt of an application for compensation the Claims Tribunal shall hold an inquiry into the claim and may make an award determining the amount of compensation which appears to it to be just and specifying the person or persons to whom compensation shall be paid.","11","Insurance / Compensation","Motor Vehicles Law",["MVA S168 MACT award just compensation determination persons paid inquiry"]],
  ["173","Appeals","Any person aggrieved by an award of a Claims Tribunal may, within ninety days from the date of the award, prefer an appeal to the High Court.","11","Insurance / Compensation","Motor Vehicles Law",["MVA S173 appeal Claims Tribunal ninety days High Court aggrieved"]],
  ["177","General provision for punishment of offences","Whoever contravenes any provision of this Act or of any rule, regulation or notification made thereunder shall, if no penalty is provided for the offence be punishable for the first offence with fine which may extend to one hundred rupees, and for any subsequent offence with fine which may extend to three hundred rupees.","15","Penalties","Motor Vehicles Law",["MVA S177 general punishment no specific penalty first one hundred subsequent three hundred contravention"]],
  ["178","Penalty for travelling without pass or ticket","Whoever travels in a stage carriage or contract carriage without passing or ticket or beyond the distance for which he holds a pass or ticket shall be punishable with fine which may extend to five hundred rupees.","15","Penalties","Motor Vehicles Law",["MVA S178 travelling without ticket pass stage carriage contract five hundred"]],
  ["181","Driving without licence","Whoever drives a motor vehicle in contravention of section 3 or section 4 shall be punishable with imprisonment for a term which may extend to three months, or with fine which may extend to five thousand rupees, or with both.","15","Penalties","Motor Vehicles Law",["MVA S181 driving without licence section 3 4 three months five thousand 2019"]],
  ["182","Driving despite disqualification","Whoever drives a motor vehicle in contravention of any order made under section 19, or in contravention of section 23, shall be punishable with imprisonment for a term which may extend to three months, or with fine which may extend to ten thousand rupees, or with both.","15","Penalties","Motor Vehicles Law",["MVA S182 driving disqualification section 19 23 three months ten thousand fine"]],
  ["183","Driving at excessive speed","Whoever drives a motor vehicle in contravention of the speed limits referred to in section 112 shall be punishable with fine which shall not be less than one thousand rupees but may extend to two thousand rupees for the first offence and not less than two thousand rupees but may extend to five thousand rupees for any subsequent offence.","15","Penalties","Motor Vehicles Law",["MVA S183 excessive speed first 1000-2000 subsequent 2000-5000 section 112"]],
  ["184","Driving dangerously","Whoever drives a motor vehicle at a speed or in a manner which is dangerous to the public, having regard to all the circumstances of the case including the nature, condition and use of the place where the vehicle is driven and the amount of traffic which actually is at the time or might reasonably be expected to be in the place, shall be punishable for the first offence with imprisonment for a term which may extend to six months, or with fine which may extend to five thousand rupees.","15","Penalties","Motor Vehicles Law",["MVA S184 dangerous driving six months five thousand first offence speed manner dangerous public"]],
  ["185","Driving by a drunken person or by a person under the influence of drugs","Whoever, while driving or attempting to drive a motor vehicle, is under the influence of alcohol or a drug to such an extent as to be incapable of exercising proper control over the vehicle, shall be punishable for a first offence with imprisonment for a term which may extend to six months or fine not less than ten thousand rupees and for a second offence with imprisonment up to two years or fine not less than fifteen thousand rupees.","15","Penalties","Motor Vehicles Law",["MVA S185 drunk driving drugs incapable control first 6 months 10000 second 2 years 15000 2019"]],
  ["190","Using vehicle in unsafe condition","Whoever uses or causes or allows to be used in any public place a motor vehicle which violates the standards prescribed in relation to road safety, road design, or environmental protection, or which is mechanically defective, shall be punishable with a fine which may extend to ten thousand rupees.","15","Penalties","Motor Vehicles Law",["MVA S190 unsafe condition road safety mechanical defect ten thousand public place standards"]],
  ["194","Driving without permit","Whoever drives a motor vehicle or causes or allows a motor vehicle to be driven in contravention of section 63 shall be punishable for the first offence with a fine not less than ten thousand rupees but not more than twenty-five thousand rupees.","15","Penalties","Motor Vehicles Law",["MVA S194 without permit S63 first offence ten twenty-five thousand fine"]],
  ["194A","Overloading of passengers","If any person drives or causes or allows to be driven any transport vehicle carrying passengers in excess of the seating capacity, he shall be punishable with a fine which shall not be less than one thousand rupees for each excess passenger.","15","Penalties","Motor Vehicles Law",["MVA S194A overloading passengers excess seating one thousand per passenger fine"]],
  ["194B","Seat belt","Whoever drives a motor vehicle or causes or allows to be driven in a public place a motor vehicle without wearing a seatbelt or allowing passengers to sit without seatbelts shall be punishable with a fine not exceeding one thousand rupees.","15","Penalties","Motor Vehicles Law",["MVA S194B seatbelt one thousand fine public place driver passenger wear"]],
  ["194C","Driving without insurance","Whoever drives a motor vehicle or causes or allows to be driven a motor vehicle in a public place without a valid insurance under Chapter XI shall be punishable with imprisonment for a term which may extend to three months or with fine which may extend to two thousand rupees, or with both.","15","Penalties","Motor Vehicles Law",["MVA S194C driving without insurance Chapter XI three months two thousand 2019"]],
  ["199A","Offences by juveniles","Where an offence has been committed by a person under the age of eighteen years, the guardian of such person or the owner of the motor vehicle shall be deemed to have committed the offence and shall be punishable with imprisonment for a term of three years and with fine of twenty-five thousand rupees and the guardian shall also be liable to be disqualified for holding a driving licence for a period of twelve months.","15","Penalties","Motor Vehicles Law",["MVA S199A juvenile offence under 18 guardian owner three years twenty-five thousand fine 12 months disqualification 2019"]],
  ["206","Power of police officer to impound document","Any police officer or other person authorised in this behalf by the State Government may, if he has reason to believe that any identification mark, number plate, permit, licence, certificate of registration, certificate of insurance or any other document produced for inspection is a false document within the meaning of section 464 of the IPC, seize and detain the document.","12","Traffic Rules","Motor Vehicles Law",["MVA S206 police impound document false section 464 IPC identification plate permit licence insurance seize"]],
];
MVA_DETAILED.forEach(([sec,title,desc,ch,cht,cat,kw])=>
  add("Motor Vehicles Act, 1988","MVA",sec,title,desc,ch,cht,cat,kw));

// ─────────────────────────────────────────────────────────────────────────────
// SECTION D: Code of Civil Procedure 1908 - additional sections
// ─────────────────────────────────────────────────────────────────────────────
const CPC_EXTRA = [
  ["1","Short title, commencement and extent","This Act may be cited as the Code of Civil Procedure, 1908. It extends to the whole of India except tribal areas and applies to all civil suits.","1","Preliminary","Civil Procedure",["CPC S1 short title commencement 1908 India extent"]],
  ["2","Definitions","'Decree' means the formal expression of an adjudication which, so far as regards the Court expressing it, conclusively determines the rights of the parties. Preliminary and final decrees. 'Judgment' means the statement given by the judge of the grounds of a decree or order. 'Order' means the formal expression of any decision of a Civil Court which is not a decree.","1","Preliminary","Civil Procedure",["CPC S2 decree judgment order preliminary final definition formal expression rights parties"]],
  ["3","Subordination of courts","For the purposes of this Code, District Courts are subordinate to the High Court, and every Civil Court of a grade inferior to that of a District Court and every Court of Small Causes is subordinate to the High Court and District Court.","1","Preliminary","Civil Procedure",["CPC S3 subordination courts District Court High Court Civil Court Small Causes inferior grade"]],
  ["4","Savings - CPC not to apply to certain proceedings","Nothing in this Code shall be deemed to limit or otherwise affect any special or local law for the time being in force, or any special form of procedure prescribed by or under any other law for the time being in force.","1","Preliminary","Civil Procedure",["CPC S4 savings special local law special procedure other law limit affect"]],
  ["6","Pecuniary jurisdiction","Save in so far as is otherwise expressly provided, nothing herein contained shall operate to give any Court jurisdiction over suits the amount or value of the subject-matter of which exceeds the pecuniary limits (if any) of its ordinary jurisdiction.","1","Preliminary","Civil Procedure",["CPC S6 pecuniary jurisdiction amount value subject-matter exceeds ordinary limits"]],
  ["10","Stay of suit - Res sub judice","No Court shall proceed with the trial of any suit in which the matter in issue is also directly and substantially in issue in a previously instituted suit between the same parties, or between parties under whom they or any of them claim, litigating under the same title, where such suit is pending in the same or any other Court in India having jurisdiction to grant the relief claimed.","2","Jurisdiction of Courts","Civil Procedure",["CPC S10 res sub judice stay suit same matter same parties pending court jurisdiction trial"]],
  ["11","Res judicata","No Court shall try any suit or issue in which the matter directly and substantially in issue has been directly and substantially in issue in a former suit between the same parties, or between parties under whom they or any of them claim, litigating under the same title, in a Court competent to try such subsequent suit or the suit in which such issue has been subsequently raised.","2","Jurisdiction of Courts","Civil Procedure",["CPC S11 res judicata former suit same parties same title same matter competent court bar subsequent"]],
  ["12","Bar to further suit","Where a plaintiff is precluded by rules from instituting a further suit in respect of any particular cause of action, he shall not be entitled to institute a suit in any court to which this Code applies on the same cause of action.","2","Jurisdiction of Courts","Civil Procedure",["CPC S12 bar further suit plaintiff cause of action precluded institute"]],
  ["13","When foreign judgment not conclusive","A foreign judgment shall be conclusive as to any matter thereby directly adjudicated upon between the same parties or between parties under whom they or any of them claim litigating under the same title except in certain cases including: not by a competent court; not on merits; against principles of natural justice; sustained on incorrect views of international or Indian law; breach of Indian law.","2","Jurisdiction of Courts","Civil Procedure",["CPC S13 foreign judgment not conclusive competent court merits natural justice Indian international law exceptions"]],
  ["14","Presumption as to foreign judgment","The court shall presume, upon production of any document purporting to be a certified copy of a foreign judgment, that such judgment was pronounced by a court of competent jurisdiction, unless the contrary appears.","2","Jurisdiction of Courts","Civil Procedure",["CPC S14 foreign judgment presumption competent jurisdiction certified copy contrary appears"]],
  ["15","Court in which suits to be instituted","Every suit shall be instituted in the Court of the lowest grade competent to try it.","2","Jurisdiction of Courts","Civil Procedure",["CPC S15 lowest court competent trial suit instituted grade"]],
  ["16","Suits to be instituted where subject-matter situate","Subject to the pecuniary or other limitations prescribed by any law, suits for the recovery of immoveable property, or for the determination of any other right to or interest in immoveable property, shall be instituted in the Court within the local limits of whose jurisdiction the property is situate.","2","Jurisdiction of Courts","Civil Procedure",["CPC S16 immoveable property situate local limits jurisdiction suit recovery determination right interest"]],
  ["17","Suits for immoveable property situate in jurisdiction of different courts","Where a suit is to recover, or determine any interest in, immoveable property situated within the jurisdiction of different courts, the suit may be instituted in any court within the local limits of whose jurisdiction any portion of the property is situated, provided that such portion is not less than the specified value.","2","Jurisdiction of Courts","Civil Procedure",["CPC S17 immoveable property different courts local limits jurisdiction portion value suit"]],
  ["18","Place of institution of suit where local limits of jurisdiction of courts are uncertain","Where it is alleged to be uncertain within the local limits of the jurisdiction of which of two or more courts any immoveable property is situate, any one of those courts may, if satisfied that there is ground for the alleged uncertainty, record a statement to that effect, and thereupon proceed to entertain and dispose of any suit relating to that property.","2","Jurisdiction of Courts","Civil Procedure",["CPC S18 uncertain jurisdiction local limits immoveable property two courts statement proceed entertain"]],
  ["19","Suits for compensation for wrongs to person or movables","Where a suit is for compensation for wrong done to the person or to moveable property, if the wrong was done within the local limits of the jurisdiction of one Court and the defendant resides, or carries on business, or personally works for gain, within the local limits of the jurisdiction of another Court, the suit may be instituted at the option of the plaintiff in either of the said Courts.","2","Jurisdiction of Courts","Civil Procedure",["CPC S19 wrong person moveable compensation option plaintiff two courts defendant resides business"]],
  ["21","Objections to jurisdiction","No objection as to the place of suing shall be allowed by any appellate or revisional court unless: (a) such objection was taken in the court of first instance at the earliest possible opportunity; (b) there has been a consequent failure of justice.","2","Jurisdiction of Courts","Civil Procedure",["CPC S21 objection jurisdiction appellate revision first instance earliest opportunity failure of justice"]],
  ["22","Power to transfer suits which may be instituted in more than one court","Where a suit may be instituted in any one of two or more Courts, and is instituted in one of such Courts, any defendant, after notice to the other parties, may, before the issue of process applying for the return of the plaint, apply to the Appellate Court to have the suit transferred to another Court.","2","Jurisdiction of Courts","Civil Procedure",["CPC S22 transfer suit two courts defendant notice plaint return appellate court"]],
  ["23","To what court application lies","Where the several Courts having jurisdiction are subordinate to the same Appellate Court, an application under the last preceding section shall be made to the Appellate Court.","2","Jurisdiction of Courts","Civil Procedure",["CPC S23 transfer application same appellate court subordinate"]],
  ["24","General power of transfer and withdrawal","On the application of any of the parties and after notice to the parties and after hearing such of them as desire to be heard, or of its own motion without such notice, the High Court or the District Court may at any stage transfer any suit, appeal or other proceeding from one Court to another.","2","Jurisdiction of Courts","Civil Procedure",["CPC S24 transfer withdrawal suit appeal High Court District Court own motion notice parties stage"]],
  ["25","Power of Supreme Court to transfer suits etc.","The Supreme Court may, on the application of a party, and after notice to the parties, and after hearing such of them as desire to be heard, transfer any suit, appeal or other proceeding from a High Court or other Civil Court in one State to a High Court or other Civil Court in any other State.","2","Jurisdiction of Courts","Civil Procedure",["CPC S25 Supreme Court transfer inter-state suit appeal civil court High Court State notice"]],
  ["26","Institution of suits","Every suit shall be instituted by the presentation of a plaint or in such other manner as may be prescribed. Prescribed means prescribed by rules.","3","Institution of Suits","Civil Procedure",["CPC S26 institution suit plaint presentation prescribed rules other manner"]],
  ["27","Summons to defendants","Where a suit has been duly instituted, a summons may be issued to the defendant to appear and answer the claim and to file a written statement of his defence on a day to be specified therein, and may be in the form prescribed.","3","Institution of Suits","Civil Procedure",["CPC S27 summons defendant appear answer written statement day specified form prescribed"]],
  ["28","Service of summons where defendant resides in another State","Where the defendant resides in another State, a Court under this Code shall issue summons to the defendant requesting the court of that other State to cause the summons to be served on the defendant.","3","Institution of Suits","Civil Procedure",["CPC S28 summons another State defendant request court service"]],
  ["29","Service of foreign summonses","Summonses and other processes issued by courts in territories outside India to which the Central Government has by notification declared the provisions of this section to apply shall be served on persons residing within India.","3","Institution of Suits","Civil Procedure",["CPC S29 foreign summons India notification Central Government service persons territories"]],
  ["30","Power to order discovery and the like","Subject to such conditions and limitations as may be prescribed, the Court may, at any time, either of its own motion or on the application of any party: order any person to discover such documents as are in his possession or power; inspect, produce, impound and return documents or other material objects producible as evidence; order any person to deliver an interrogatory.","3","Institution of Suits","Civil Procedure",["CPC S30 discovery inspection documents interrogatory court order own motion application possession power evidence"]],
  ["32","Penalty for default","The Court may compel the attendance of any person to whom a summons has been issued under section 30 by issuing a warrant for his arrest, or by attaching and selling his property, or by imposing a fine not exceeding five thousand rupees, or by imprisoning him in civil prison for a term not exceeding six months.","3","Institution of Suits","Civil Procedure",["CPC S32 penalty default attendance summons arrest attachment fine five thousand civil prison six months"]],
  ["33","Judgment and decree","The Court, after the case has been heard, shall pronounce judgment, and on such judgment a decree shall follow.","3","Institution of Suits","Civil Procedure",["CPC S33 judgment decree heard court pronounce follow"]],
  ["34","Interest","Where and in so far as a decree is for the payment of money, the Court may, in the decree, order interest at such rate as the Court deems reasonable to be paid on the principal sum adjudged, from the date of the suit to the date of the decree, in addition to any interest adjudged on such principal sum for any period prior to the institution of the suit.","4","Execution","Civil Procedure",["CPC S34 interest decree money rate reasonable date suit decree adjudged principal"]],
  ["35","Costs","Subject to such conditions and limitations as may be prescribed, and to the provisions of any law for the time being in force, the costs of and incident to all suits shall be in the discretion of the Court, and the Court shall have full power to determine by whom or out of what property and to what extent such costs are to be paid.","4","Execution","Civil Procedure",["CPC S35 costs discretion court extent property paid suit incident limitations full power"]],
  ["35A","Compensatory costs in respect of false or vexatious claims or defences","If in any suit or other proceedings any party objects to the claim or defence on the ground that the claim or defence or any part of it is false or vexatious to the knowledge of the party by whom it has been put forward, and if thereafter the claim or defence is disallowed, abandoned or withdrawn in whole or in part, the Court may, if it so thinks fit, after recording its reasons for holding the claim or defence to be false or vexatious, make an order for the payment to the objector of compensatory costs not exceeding three thousand rupees in respect of his objection.","4","Execution","Civil Procedure",["CPC S35A compensatory costs false vexatious claim defence three thousand court reasons disallowed abandoned"]],
  ["36","Application to orders","The provisions of this Code relating to the execution of decrees shall, so far as they are applicable, be deemed to apply to the execution of orders.","4","Execution","Civil Procedure",["CPC S36 execution orders applicable deemed apply decrees"]],
  ["38","Court by which decree may be executed","A decree may be executed either by the Court which passed it, or by the Court to which it is sent for execution.","4","Execution","Civil Procedure",["CPC S38 execution decree court passed sent"]],
  ["39","Transfer of decree","The Court which passed a decree may, on the application of the decree-holder, send it for execution to another Court.","4","Execution","Civil Procedure",["CPC S39 transfer decree decree-holder application another court execution"]],
  ["44A","Execution of decrees passed by Courts in reciprocating territory","Where a certified copy of decree of any of the superior courts of any reciprocating territory has been filed in a District Court, the decree may be executed in India as if it had been passed by the District Court.","4","Execution","Civil Procedure",["CPC S44A execution reciprocating territory superior court certified copy District Court India"]],
  ["51","Powers of Court to enforce execution","Subject to such conditions and limitations as may be prescribed, the Court may, on the application of the decree-holder, order execution of the decree by delivery of any property specifically decreed; attachment and sale of property; arrest and detention in prison of the judgment-debtor; appointment of a receiver; in such other manner as the nature of the relief granted may require.","4","Execution","Civil Procedure",["CPC S51 powers execution delivery property attachment sale arrest detention prison receiver judgment-debtor decree-holder"]],
  ["54","Partition of estate or separation of share","Where the decree is for the partition of an undivided estate assessed to the payment of revenue to the Government, or for the separate possession of a share of such an estate, the partition of the estate or the separation of the share shall be made by the Collector or any gazetted subordinate of the Collector deputed by him in this behalf.","4","Execution","Civil Procedure",["CPC S54 partition undivided estate revenue Collector gazetted subordinate decree separate possession"]],
  ["55","Arrest and detention","A judgment-debtor may be arrested in execution of a decree at any hour and on any day, and shall be brought before the Court as soon as practicable. No order for the arrest of a judgment-debtor shall be made unless the court is satisfied that there is reason to believe that the judgment-debtor with intent to obstruct or delay the execution has absconded or left the local limits.","4","Execution","Civil Procedure",["CPC S55 arrest detention judgment-debtor execution decree hour day brought court intent obstruct absconded local limits"]],
  ["60","Property liable to attachment and sale in execution of decree","The following property is liable to attachment and sale in execution of a decree: lands, houses and other buildings; goods, money, banknotes, cheques, bills of exchange, hundis, promissory notes, Government securities; debts; shares in a corporation; salary; salary above specified limit.","4","Execution","Civil Procedure",["CPC S60 property attachment sale execution decree lands houses goods money salary shares debts Government securities"]],
  ["62","Attachment of property in custody of court or public officer","Where the property to be attached is in the custody of any court or public officer, the attachment shall be made by a notice to such court or officer, requesting that such property, and any interest or dividend becoming payable thereon, may be held subject to the further orders of the court from which the notice is issued.","4","Execution","Civil Procedure",["CPC S62 attachment property court custody public officer notice interest dividend hold further orders"]],
  ["64","Private alienations of property after attachment to be void","Where an attachment has been made, any private transfer or delivery of the property attached or of any interest therein and any payment to the judgment-debtor of any debt, dividend or other monies contrary to such attachment, shall be void as against all claims enforceable under the attachment.","4","Execution","Civil Procedure",["CPC S64 private alienation void attachment transfer delivery interest debt judgment-debtor enforceable"]],
  ["74","Arrest in execution - procedure","A judgment-debtor arrested in execution of a decree may be committed to the civil prison and shall be detained therein for the following periods: not exceeding the period of one year where the decree is for payment of a sum exceeding five thousand rupees. For sum exceeding two thousand but not five thousand: six months. For two thousand rupees or below: no imprisonment.","4","Execution","Civil Procedure",["CPC S74 civil prison arrest execution one year five thousand six months two thousand imprisonment period"]],
  ["79","Suits by or against Government","In a suit by or against the Government, the authority to be named as plaintiff or defendant, as the case may be, shall be the Union of India, where the suit is by or against the Central Government, and the State Government in other cases.","5","Special Proceedings","Civil Procedure",["CPC S79 suit government plaintiff defendant Union of India State Government central"]],
  ["81","Exemption from arrest and personal appearance","No one shall be arrested in execution of any decree in any suit for the recovery of money, if he is a member of Parliament or a member of a State Legislature, during any session of the House of which he is a member, or during the forty days before or after such session.","5","Special Proceedings","Civil Procedure",["CPC S81 exemption arrest Parliament State Legislature member session forty days before after"]],
  ["83","When foreign states may sue","A foreign State may sue in any Court in India if it is recognised by the Central Government, by a suit for the enforcement of private rights vested in the head of such State, or for the recovery of any private debt owing to such State.","5","Special Proceedings","Civil Procedure",["CPC S83 foreign state sue India Central Government recognised private rights head debt recovery"]],
  ["86","Suits against foreign States","No foreign State and no ruler of a foreign State shall be sued in any Court except with the consent of the Central Government certified in writing by a Secretary to that Government.","5","Special Proceedings","Civil Procedure",["CPC S86 suit foreign state ruler consent Central Government certified secretary writing"]],
  ["87A","Definitions of Foreign State and ruler","In this Code, 'Foreign State' means any State outside India which has been recognised by the Central Government; and 'ruler' in relation to a foreign State includes the person who was recognised by the Central Government as the ruler of that foreign State immediately before the commencement of the Constitution.","5","Special Proceedings","Civil Procedure",["CPC S87A foreign state ruler definition recognised Central Government Constitution outside India"]],
  ["89","Settlement of disputes outside the court - ADR","Where it appears to the court that there exist elements of a settlement which may be acceptable to the parties, the court shall formulate the terms of settlement and give them to the parties for their observations and after receiving the observations of the parties, the court may reformulate the terms of a possible settlement and refer the same for arbitration, conciliation, judicial settlement including settlement through Lok Adalat, or mediation.","5","Special Proceedings","Civil Procedure",["CPC S89 ADR settlement outside court arbitration conciliation Lok Adalat mediation judicial settlement 2002 amendment"]],
  ["91","Public nuisances and other wrongful acts affecting public","In the case of a public nuisance or other wrongful act affecting, or likely to affect, the public, a suit for a declaration and injunction or for such other relief as may be appropriate in the circumstances of the case may be instituted - by the Advocate-General or with the leave of the Court by two or more persons, even if no special damage has been caused to such persons by such public nuisance.","5","Special Proceedings","Civil Procedure",["CPC S91 public nuisance injunction declaration Advocate-General two persons leave court no special damage"]],
  ["92","Public charities","In the case of any alleged breach of any express or constructive trust created for public purposes of a charitable or religious nature, or where the direction of the court is deemed necessary for the administration of any such trust, the Advocate-General, or two or more persons having an interest in the trust and having obtained the leave of the court, may institute a suit, whether contentious or not.","5","Special Proceedings","Civil Procedure",["CPC S92 public charity trust breach Advocate-General leave two persons religious charitable administration"]],
  ["94","Supplemental proceedings","In order to prevent the ends of justice from being defeated, the Court may, if it is so prescribed, make any order for the temporary custody and preservation of property which is the subject-matter of a suit.","5","Special Proceedings","Civil Procedure",["CPC S94 supplemental proceedings temporary custody preservation property subject-matter suit ends of justice"]],
  ["95","Compensation for obtaining arrest, attachment or injunction on insufficient grounds","Where, in any suit, arrest or attachment has been effected, or a temporary injunction has been granted, on the application of the plaintiff and it appears to the court that the application was made on insufficient grounds, the court may, on the application of the defendant, award reasonable compensation to the defendant for the expense or injury caused to him.","5","Special Proceedings","Civil Procedure",["CPC S95 compensation arrest attachment injunction insufficient grounds plaintiff defendant reasonable expense injury"]],
  ["100","Second appeal","Save as otherwise expressly provided in the body of this Code or by any other law for the time being in force, an appeal shall lie to the High Court from every decree passed in appeal by any court subordinate to the High Court, if the High Court is satisfied that the case involves a substantial question of law.","8","Appeals","Civil Procedure",["CPC S100 second appeal High Court substantial question of law decree subordinate court"]],
  ["101","Second appeal on no other grounds","No second appeal shall lie except on the grounds mentioned in section 100.","8","Appeals","Civil Procedure",["CPC S101 second appeal grounds only section 100 limited"]],
  ["104","Orders from which appeal lies","Appeals shall lie from the following orders, and save as otherwise expressly provided in the body of this Code or by any other law for the time being in force, from no other orders: orders under section 35A; orders rejecting application to set aside sale of immoveable property; orders of refusal to set aside ex parte decree; orders determining any claim or question relating to execution; orders in interpleader suits.","8","Appeals","Civil Procedure",["CPC S104 orders appeal lie S35A sale immoveable ex parte execution interpleader specified"]],
  ["106","What Courts to hear appeals from orders under Part II","Appeals from orders mentioned in section 104 shall lie to the court to which an appeal from the suit would lie.","8","Appeals","Civil Procedure",["CPC S106 appeals orders Part II court suit appeal lies"]],
  ["107","Powers of Appellate Court","Subject to such conditions and limitations as may be prescribed, an Appellate Court shall have power to determine a case finally; to remand a case; to frame issues and refer them for trial; to take additional evidence or to require such evidence to be taken. The appellate court can pronounce the judgment the trial court ought to have pronounced.","8","Appeals","Civil Procedure",["CPC S107 appellate court powers determine finally remand frame issues additional evidence judgment trial ought"]],
  ["113","Reference to High Court","Subject to such conditions and limitations as may be prescribed, any Court may state a case and refer the same for the opinion of the High Court, and the High Court may make such order thereon as it thinks fit.","8","Appeals","Civil Procedure",["CPC S113 reference High Court state case opinion order"]],
  ["114","Review","Subject as aforesaid, any person considering himself aggrieved by a decree or order from which an appeal is allowed but from which no appeal has been preferred, a decree or order from which no appeal is allowed, or a decision on a reference from a court of small causes, may apply for a review of judgment to the Court which passed the decree or made the order.","8","Appeals","Civil Procedure",["CPC S114 review aggrieved decree order no appeal preferred decision small causes court passed"]],
  ["115","Revision","The High Court may call for the record of any case which has been decided by any court subordinate to such High Court and in which no appeal lies thereto, and if such subordinate court appears to have exercised a jurisdiction not vested in it by law, or to have failed to exercise a jurisdiction so vested, or to have acted in the exercise of its jurisdiction illegally or with material irregularity, the High Court may make such order in the case as it thinks fit.","8","Appeals","Civil Procedure",["CPC S115 revision High Court subordinate no appeal jurisdiction not vested failed illegally material irregularity order"]],
];
CPC_EXTRA.forEach(([sec,title,desc,ch,cht,cat,kw])=>
  add("Code of Civil Procedure, 1908","CPC",sec,title,desc,ch,cht,cat,kw));

// ─────────────────────────────────────────────────────────────────────────────
// SECTION E: CrPC detailed sections not already covered
// ─────────────────────────────────────────────────────────────────────────────
const CRPC_EXTRA = [
  ["4","Trial of offences under IPC and other laws","All offences under the IPC shall be investigated, inquired into, tried, and otherwise dealt with according to the provisions hereinafter contained. All offences under any other law shall be investigated, inquired into, tried, and otherwise dealt with according to the same provisions, subject to any enactment for the time being in force regulating the manner or place of investigating, inquiring into, trying or otherwise dealing with such offences.","1","Preliminary","Criminal Procedure",["CrPC S4 trial offences IPC other laws investigated inquired tried dealt provisions"]],
  ["5","Saving","Nothing in this Code shall, in the absence of a specific provision to the contrary, affect any special or local law for the time being in force, or any special jurisdiction or power conferred, or any special form of procedure prescribed, by any other law for the time being in force.","1","Preliminary","Criminal Procedure",["CrPC S5 saving special local law jurisdiction power procedure prescribed"]],
  ["6","Classes of criminal courts","Besides the High Courts and the Courts constituted under any law, other than this Code, there shall be, in every State, the following classes of Criminal Courts: Courts of Session; Judicial Magistrates of the first class; Judicial Magistrates of the second class; Executive Magistrates.","1","Preliminary","Criminal Procedure",["CrPC S6 criminal courts classes Sessions Judicial Magistrate first second class Executive"]],
  ["7","Territorial divisions","Every State shall be a sessions division or shall consist of sessions divisions; and every sessions division shall, for the purposes of this Code, be a district or consist of districts.","1","Preliminary","Criminal Procedure",["CrPC S7 territorial divisions sessions division district State"]],
  ["8","Court of Session","The State Government shall establish a Court of Session for every sessions division, and there shall be a Judge of every such Court to be called the Sessions Judge.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S8 Court of Session sessions division Judge State Government established"]],
  ["9","Courts of Judicial Magistrates","In every district not being a metropolitan area there shall be established as many Courts of Judicial Magistrates of the first class and of the second class as the State Government may, after consultation with the High Court, by notification, think fit to establish.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S9 Judicial Magistrates first second class district courts State Government High Court consultation notification"]],
  ["10","Chief Judicial Magistrate and Additional Chief Judicial Magistrate","In every district, the High Court shall appoint a Judicial Magistrate of the first class to be the Chief Judicial Magistrate. The Chief Judicial Magistrate shall be subordinate to the Sessions Judge and every other Judicial Magistrate shall be subordinate to the Chief Judicial Magistrate.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S10 Chief Judicial Magistrate district High Court appoint first class subordinate Sessions Judge"]],
  ["11","Courts of Metropolitan Magistrates","In every metropolitan area, there shall be established as many Courts of Metropolitan Magistrates as the State Government may, after consultation with the High Court, by notification, think fit to establish.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S11 Metropolitan Magistrates metropolitan area State Government High Court notification establish"]],
  ["12","Chief Metropolitan Magistrate","In every metropolitan area, the High Court shall appoint a Metropolitan Magistrate to be the Chief Metropolitan Magistrate who shall be subordinate to the Sessions Judge.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S12 Chief Metropolitan Magistrate High Court appoint metropolitan area subordinate Sessions Judge"]],
  ["13","Special Judicial Magistrates","The High Court may, if requested by the Central or State Government, confer upon any person who holds or has held any post under the Government all or any of the powers conferred or conferrable by or under this Code on a Judicial Magistrate in respect to particular cases or to a particular class or classes of cases.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S13 Special Judicial Magistrate High Court Central State Government confer powers post particular cases"]],
  ["15","Subordination of Executive Magistrates","All Executive Magistrates, other than the Additional District Magistrate, shall be subordinate to the District Magistrate, and every Executive Magistrate shall also be subordinate to such other Executive Magistrate (if any) as the State Government may direct.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S15 subordination Executive Magistrates District Magistrate Additional State Government direction"]],
  ["16","Courts of Metropolitan Magistrates - subordination","Every Metropolitan Magistrate shall be subordinate to the Sessions Judge of the sessions division the local limits of which include the metropolitan area, and (subject to the control of the Sessions Judge) to the Chief Metropolitan Magistrate.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S16 Metropolitan Magistrate subordinate Sessions Judge metropolitan area Chief Metropolitan control"]],
  ["19","Appointment of Special Executive Magistrates","The State Government may appoint, for such term as it may think fit, Executive Magistrates to be known as Special Executive Magistrates for particular areas or for the performance of particular functions and confer on such Special Executive Magistrates such of the powers as are conferrable under this Code on Executive Magistrates.","2","Constitution of Criminal Courts","Criminal Procedure",["CrPC S19 Special Executive Magistrate State Government appoint term powers particular area function"]],
  ["25","Public Prosecutors","The Central Government or State Government may appoint a person as a Public Prosecutor or as an Additional Public Prosecutor for the purpose of conducting any case or class of cases. The Government may also appoint Advocates as Special Public Prosecutors for specific cases.","3","Power of Courts","Criminal Procedure",["CrPC S25 Public Prosecutor Additional Central State Government appoint Advocate Special case conduct"]],
  ["26","Courts by which offences are triable","Subject to the other provisions of this Code, any offence under the Indian Penal Code may be tried by the High Court, the Court of Session, the Court of a Chief Judicial Magistrate, the Court of a Judicial Magistrate of the first class, or by the Court of a Magistrate of the second class, as the First Schedule to this Code specifies.","3","Power of Courts","Criminal Procedure",["CrPC S26 offences triable High Court Sessions CJM JMFC Second Class First Schedule IPC"]],
  ["27","Jurisdiction in the case of juveniles","Any offence not punishable with death or imprisonment for life, committed by any person who at the date when he appears or is brought before the court is under the age of sixteen years, may be tried by the Court of a Chief Judicial Magistrate, or by any Court specially empowered under the Children Act, 1960 or any other law for the time being in force.","3","Power of Courts","Criminal Procedure",["CrPC S27 juvenile under sixteen years offence CJM special court Children Act not death life"]],
  ["29","Sentences which Magistrates may pass","The Court of a Chief Judicial Magistrate may pass any sentence authorised by law except a sentence of death or of imprisonment for life or of imprisonment for a term exceeding seven years. The Court of a Magistrate of the first class may pass a sentence of imprisonment for a term not exceeding three years, or of fine not exceeding ten thousand rupees, or of both.","3","Power of Courts","Criminal Procedure",["CrPC S29 sentence Magistrate CJM seven years first class three years ten thousand fine not death life"]],
  ["30","Sentence of imprisonment in default of fine","The Court of a Magistrate may award such term of imprisonment in default of payment of fine as is authorised by law: Provided that the term (a) is not in excess of the powers under the last preceding section; (b) shall not, where imprisonment has been awarded as part of the substantive sentence, exceed one-fourth of the term of imprisonment which the Magistrate is competent to inflict as the maximum sentence for the offence otherwise than as a sentence in default of payment of fine.","3","Power of Courts","Criminal Procedure",["CrPC S30 imprisonment default fine Magistrate term powers one-fourth maximum sentence substantive"]],
  ["31","Sentences in cases of conviction of several offences at one trial","When a person is convicted at one trial of two or more offences, the Court may, subject to the provisions of section 71 of the Indian Penal Code, sentence him for such offences, to the several punishments prescribed therefor which such Court is competent to inflict.","3","Power of Courts","Criminal Procedure",["CrPC S31 sentence several offences one trial consecutive concurrent S71 IPC competent court"]],
  ["36","Powers of superior officers of police","Police officers superior in rank to an officer in charge of a police station may exercise the same powers, throughout the local area to which they are appointed, as may be exercised by such officer within the limits of his station.","3","Power of Courts","Criminal Procedure",["CrPC S36 superior police officer powers local area station limits exercise"]],
  ["37","Public when to assist Magistrates and police","Every person is bound to assist a Magistrate or police officer reasonably demanding his aid: in the taking or preventing the escape of any other person whom such Magistrate or police officer is authorised to arrest; in the prevention or suppression of a breach of the peace; in the prevention of any injury attempted to be committed to any railway, canal, telegraph or public property.","3","Power of Courts","Criminal Procedure",["CrPC S37 public assist Magistrate police arrest escape breach peace injury railway property"]],
  ["38","Aid to person other than police officer executing warrant","When a warrant is directed to a person other than a police officer, any other person may aid in the execution of such warrant, if the person to whom the warrant is directed be near at hand and acting in the execution of the warrant.","3","Power of Courts","Criminal Procedure",["CrPC S38 aid warrant person not police officer execution near hand acting"]],
  ["39","Public to give information of certain offences","Every person, aware of the commission of, or of the intention of any other person to commit, any offence punishable under certain sections of the IPC (including those relating to waging war, sedition, murder, dacoity, etc.), shall forthwith give information to the nearest Magistrate or police officer.","3","Power of Courts","Criminal Procedure",["CrPC S39 public information commission intention offence murder dacoity waging war sedition nearest Magistrate police forthwith"]],
  ["40","Duty of officers employed in connection with affairs of a village to make certain report","Every officer employed in connection with the affairs of a village and every person residing in a village shall forthwith communicate to the nearest Magistrate or to the officer in charge of the nearest police station, whichever is nearer, any information which he may possess respecting: the permanent or temporary residence of any notorious receiver or vendor of stolen property; the resort to any place within the village of any person known to be a thug, escaped convict or proclaimed offender.","3","Power of Courts","Criminal Procedure",["CrPC S40 village officer information notorious receiver stolen thug escaped convict proclaimed offender Magistrate police"]],
  ["43","Arrest by private person and procedure on such arrest","Any private person may arrest or cause to be arrested any person who in his presence commits a non-bailable and cognizable offence, or any proclaimed offender, and, without unnecessary delay, shall make over or cause to be made over any person so arrested to a police officer, or, in the absence of a police officer, take such person or cause him to be taken in custody to the nearest police station.","5","Arrest","Criminal Procedure",["CrPC S43 private person arrest cognizable non-bailable presence proclaimed offender police station nearest without delay"]],
  ["44","Arrest by Magistrate","When any offence is committed in the presence of a Magistrate, whether Executive or Judicial, within his local jurisdiction, he may himself arrest or order any person to arrest the offender, and may thereupon, subject to the provisions herein contained as to bail, commit the offender to custody.","5","Arrest","Criminal Procedure",["CrPC S44 arrest Magistrate presence offence committed Executive Judicial local jurisdiction commit custody bail"]],
  ["45","Protection of members of the Armed Forces from arrest","Notwithstanding anything contained in sections 41 to 44, no member of the Armed Forces of the Union shall be arrested for anything done or purported to be done by him in the discharge of his official duties except after obtaining the consent of the Central Government.","5","Arrest","Criminal Procedure",["CrPC S45 protection Armed Forces arrest official duties Central Government consent sections 41-44"]],
  ["47","Search of place entered by person sought to be arrested","If any person acting under a warrant of arrest, or any police officer having authority to arrest, has reason to believe that the person to be arrested has entered into, or is within, any place, any person residing in, or being in charge of, such place shall, on demand of such person acting as aforesaid or such police officer, allow him free ingress thereto, and afford all reasonable facilities for a search therein.","5","Arrest","Criminal Procedure",["CrPC S47 search place warrant arrest police officer ingress facilities person sought believe entered"]],
  ["48","Pursuit of offenders into other jurisdictions","A police officer may, for the purpose of arresting without warrant any person whom he is authorised to arrest, pursue such person into any place in India.","5","Arrest","Criminal Procedure",["CrPC S48 pursuit offender police officer jurisdiction India arrest without warrant pursue"]],
  ["49","No unnecessary restraint","The person arrested shall not be subjected to more restraint than is necessary to prevent his escape.","5","Arrest","Criminal Procedure",["CrPC S49 no unnecessary restraint arrested person necessary prevent escape minimum force"]],
  ["51","Search of arrested person","Whenever a person is arrested by a police officer under a warrant which does not provide for the taking of bail, or under a warrant which provides for the taking of bail but the person arrested cannot furnish bail, and whenever a person is arrested without warrant or by a private person under a warrant, and cannot legally be admitted to bail, or is unable to furnish bail, the officer making the arrest or, when the arrest is made by a private person, the police officer to whom he makes over the person arrested, may search such person.","5","Arrest","Criminal Procedure",["CrPC S51 search arrested person without bail warrant private person police officer seize articles"]],
  ["52","Power to seize offensive weapons","The officer or other person making any arrest under this Code may take from the person arrested any offensive weapons which he has about his person, and shall deliver all weapons so taken to the Court or officer before which or whom the officer or person making the arrest is required by this Code to produce the person arrested.","5","Arrest","Criminal Procedure",["CrPC S52 seize offensive weapons arrest officer person deliver court produce offensive weapons"]],
  ["53A","Examination of person accused of rape by medical practitioner","When a person is arrested on a charge of committing an offence of rape or an attempt to commit rape and there are reasonable grounds for believing that an examination of his person will afford evidence as to the commission of such offence, it shall be lawful for a registered medical practitioner, to examine such person.","5","Arrest","Criminal Procedure",["CrPC S53A accused rape examination medical practitioner registered reasonable grounds evidence commit offence"]],
  ["54A","Identification of person arrested","Where a person is arrested, he may be required to stand in an identification parade and the result of such identification parade shall be communicated to the court before which the accused is produced.","5","Arrest","Criminal Procedure",["CrPC S54A identification parade arrested person result court produced accused"]],
  ["56","Person arrested to be taken before Magistrate or officer in charge of police station","A police officer making an arrest without warrant shall, without unnecessary delay and subject to the provisions herein contained as to bail, take or send the person arrested before a Magistrate having jurisdiction in the case, or before the officer in charge of a police station.","5","Arrest","Criminal Procedure",["CrPC S56 arrested person taken Magistrate police station officer without delay jurisdiction bail"]],
  ["58","Police to report apprehensions","Officers in charge of police stations shall report to the District Magistrate, or, if the District Magistrate so directs, to the Sub-divisional Magistrate, the cases of all persons arrested without warrant within the limits of their respective stations, whether such persons have been admitted to bail or otherwise.","5","Arrest","Criminal Procedure",["CrPC S58 police report apprehension District Magistrate Sub-divisional arrested without warrant bail cases"]],
  ["59","Discharge of person apprehended","No person who has been arrested by a police officer shall be discharged except on his own bond, or on bail, or under the special order of a Magistrate.","5","Arrest","Criminal Procedure",["CrPC S59 discharge arrested person bond bail special order Magistrate"]],
  ["60A","Arrest to be made strictly according to the Code","No arrest shall be made except in accordance with the provisions of this Code or any other law for the time being in force providing for arrest.","5","Arrest","Criminal Procedure",["CrPC S60A arrest strictly according Code provisions law force"]],
];
CRPC_EXTRA.forEach(([sec,title,desc,ch,cht,cat,kw])=>
  add("Code of Criminal Procedure, 1973","CrPC",sec,title,desc,ch,cht,cat,kw));

// ─────────────────────────────────────────────────────────────────────────────
// SECTION F: Indian Divorce Act 1869 - all key sections
// ─────────────────────────────────────────────────────────────────────────────
const IDA_EXTRA = [
  ["2","Extent of Act","This Act extends to the whole of India, except the territories added to India by the Indian Independence Act 1947 [now irrelevant after partition]. The Act applies to Christians and to all persons who are not governed by any other personal law (before the Special Marriage Act).","1","Preliminary","Family Law",["IDA extent India Christians applicable personal law"]],
  ["7","Jurisdiction of High Court in divorce","The High Court has jurisdiction in matrimonial cases under this Act to dissolve marriages of Christians, to grant decrees of judicial separation, nullity, and restitution of conjugal rights.","2","Jurisdiction","Family Law",["IDA jurisdiction High Court matrimonial divorce judicial separation nullity restitution conjugal rights Christians"]],
  ["10","Grounds for dissolution of marriage","Any husband may present a petition to the District Court or High Court praying that his marriage may be dissolved on the ground that his wife has, since the solemnisation of the marriage, been guilty of adultery. Any wife may present a petition praying that her marriage may be dissolved on various grounds including adultery, cruelty, desertion for 2 years, etc. (amended for gender equality in 2001).","2","Grounds","Family Law",["IDA divorce grounds adultery cruelty desertion 2 years wife husband District Court High Court 2001 amendment gender equal"]],
  ["10A","Dissolution by mutual consent","Subject to the provisions of this Act and the rules made thereunder, a petition for dissolution of marriage may be presented to the District Court by both the parties to the marriage together. The petition for divorce by mutual consent can be presented and a decree may be passed after 6 months but not after 18 months.","2","Grounds","Family Law",["IDA mutual consent divorce Section 10A 6 months 18 months parties together 2001 amendment"]],
  ["14","Petition for dissolution","No petition for dissolution of marriage shall be presented to the court unless: (a) at the date of presentation of the petition three years have passed since the date of the marriage; (b) the petitioner resides within the jurisdiction of the court at the time.","2","Grounds","Family Law",["IDA petition dissolution three years marriage date jurisdiction resides"]],
  ["17","Decree for dissolution","In a suit for dissolution of marriage, if the Court is satisfied on the evidence that the case of the petitioner has been proved, and does not find that the petitioner has been in any manner accessory to or conniving at the going through of the form of marriage, or that both the parties have condoned the adultery, it shall pronounce a decree nisi for dissolution of the marriage.","3","Decrees","Family Law",["IDA decree dissolution Court proved petitioner not accessory conniving condoned adultery nisi"]],
  ["20","Decree absolute","After the making of a decree nisi, the Court shall, on the application of the petitioner, make such decree absolute unless sufficient cause is shown why it should not be made so. The interval between decree nisi and decree absolute allows other parties to intervene.","3","Decrees","Family Law",["IDA decree absolute nisi application petitioner sufficient cause interval intervention"]],
  ["22","Alimony pendente lite","In any suit under this Act, the wife may apply to the Court for maintenance pending suit, and the Court shall ascertain whether the wife has any separate property, and if it thinks fit, may order the husband to pay to the wife the costs of such suit, and such monthly or weekly sums for her maintenance and support as the Court may think reasonable.","4","Alimony","Family Law",["IDA alimony pendente lite wife application maintenance pending suit husband monthly weekly reasonable costs"]],
  ["36","Permanent alimony","On any decree absolute of dissolution of marriage or of nullity of marriage, the Court may order the husband to secure to the wife such gross sum of money, or such annual sum of money for any term not exceeding her own life, as the Court thinks reasonable, having regard to her fortune, if any, the ability of the husband, and the conduct of the parties.","4","Alimony","Family Law",["IDA permanent alimony dissolution nullity husband wife sum annual term life reasonable fortune conduct ability"]],
  ["37","Variation of orders for payment of alimony","Where the Court has made an order or decree for alimony, it may at any time, upon application by petition of either party, discharge, vary or suspend the same on the ground of changed circumstances.","4","Alimony","Family Law",["IDA variation alimony order changed circumstances discharge vary suspend petition application either party"]],
];
IDA_EXTRA.forEach(([sec,title,desc,ch,cht,cat,kw])=>
  add("Indian Divorce Act, 1869","IDA",sec,title,desc,ch,cht,cat,kw));

// ─────────────────────────────────────────────────────────────────────────────
// SECTION G: Legal Concepts - comprehensive entries
// ─────────────────────────────────────────────────────────────────────────────
const LEGAL_CONCEPTS = [
  // Torts
  ["TORT1","Negligence - Donoghue v Stevenson principle","Negligence in tort requires: (1) duty of care; (2) breach of duty; (3) damage. Lord Atkin's 'neighbour principle' (Donoghue v Stevenson 1932): you must take reasonable care to avoid acts or omissions which you can reasonably foresee would injure your neighbour. In India: Jacob Mathew v State of Punjab (2005) - medical negligence; MC Mehta v Union of India (1987) - absolute liability. Elements: foreseeability, proximity, and it is fair/just/reasonable to impose duty.","Torts","Legal Concepts","Tort Law",["negligence duty of care breach damage Donoghue Stevenson neighbour principle Jacob Mathew MC Mehta absolute liability foreseeability proximity"]],
  ["TORT2","Occupier's Liability","An occupier of premises owes different duties to different classes of visitors: invitees (highest duty - all reasonable care); licensees (warn of known dangers); trespassers (no duty except not to set traps deliberately). In India, the distinction is somewhat different - courts apply general negligence principles. Premises includes land, buildings, and fixed structures.","Torts","Legal Concepts","Tort Law",["occupier liability invitee licensee trespasser duty care premises trap deliberately warn visitor India courts"]],
  ["TORT3","Absolute liability - MC Mehta principle (India)","In India, Justice PN Bhagwati in MC Mehta v Union of India (Oleum gas leak case, 1987) held that an enterprise engaged in a hazardous or inherently dangerous activity owes an absolute and non-delegable duty to the community to ensure no harm results from such activity. There are NO exceptions to absolute liability (unlike Rylands v Fletcher where act of God, act of stranger, consent, statutory authority are exceptions). Applicable to: chemical factories, nuclear plants, gas pipelines.","Torts","Legal Concepts","Tort Law",["absolute liability MC Mehta 1987 hazardous activity no exceptions Rylands Fletcher India non-delegable duty community PN Bhagwati"]],
  ["TORT4","Vicarious liability - employer and employee","An employer is vicariously liable for torts committed by an employee in the course of employment. Test: (1) was there a relationship of employer-employee? (2) was the act done in the course of employment? Frolic and detour: if employee goes on a frolic of his own (personal deviation), employer not liable. Independent contractor: employer generally not liable for independent contractor's acts (exceptions: non-delegable duties, inherently dangerous work).","Torts","Legal Concepts","Tort Law",["vicarious liability employer employee course of employment frolic detour independent contractor non-delegable inherently dangerous IPC S149"]],
  ["TORT5","Defamation in tort","Defamation in civil law: (a) Libel - written, permanent form - actionable per se; (b) Slander - spoken, transient form - actionable only on proof of special damage (with exceptions). Elements: (1) false statement of fact; (2) published to third person; (3) concerning the plaintiff; (4) caused damage to reputation. Defences: truth (justification); fair comment; privilege (absolute/qualified); innocent dissemination. Online defamation (cyber defamation) treated as libel.","Torts","Legal Concepts","Tort Law",["defamation libel slander false statement published third person reputation truth fair comment privilege absolute qualified cyber online IPC S499"]],
  ["TORT6","Nuisance - private and public","Private nuisance: unreasonable interference with use and enjoyment of land. Elements: (1) indirect interference; (2) unreasonable; (3) damage. Defences: prescription (20 years); statutory authority; consent. Public nuisance: affects community at large - remedy under S.268/290 IPC or CrPC S.133. Coming to nuisance: not a defence. Sensitivity of plaintiff: no defence for defendant.","Torts","Legal Concepts","Tort Law",["nuisance private public land use enjoyment unreasonable damage prescription statutory authority S268 S290 IPC CrPC S133 community coming to nuisance sensitivity"]],
  // Contract Law concepts
  ["CON1","Doctrine of frustration - expanded","S.56 ICA: Agreement to do impossible act is void. Doctrine of frustration (Taylor v Caldwell, Krell v Henry): when performance becomes impossible or radically different from what was contracted for. Categories: physical impossibility; subsequent illegality; frustration of purpose (coronation cases); death/incapacity of personal service. Not frustration: mere increase in cost, difficulty in performance, commercial hardship. Indian law: S.56 broader than common law - covers radical change in obligation.","Contracts","Legal Concepts","Contract Law",["frustration S56 ICA impossible radical different Taylor Caldwell Krell Henry subsequent illegality death incapacity not mere cost hardship Indian broader"]],
  ["CON2","Doctrine of privity of contract","Only parties to a contract can sue on it and be bound by it. Dunlop Pneumatic Tyre Co v Selfridge (1915). Exceptions in India: trusts; agency; beneficiaries named in contract; marriage settlements; assignment of benefit. S.37 ICA: parties must perform. S.2(h) ICA: contract between parties. SC in M.C. Chacko case allowed family members to sue on a family settlement. Privity is more relaxed in India than in England.","Contracts","Legal Concepts","Contract Law",["privity contract parties only Dunlop Selfridge exceptions trust agency beneficiary assignment India relaxed family settlement M.C. Chacko"]],
  ["CON3","Quasi-contracts - unjust enrichment","S.68-72 ICA: obligations resembling contracts even without agreement. Types: claim for necessaries supplied to minor/lunatic (S.68); reimbursement of money paid by interested party (S.69); obligation of person enjoying benefit of non-gratuitous act (S.70); responsibility of finder of goods (S.71); liability of person to whom money paid by mistake (S.72). Foundation: prevention of unjust enrichment. No agreement needed. Court imposes obligation.","Contracts","Legal Concepts","Contract Law",["quasi-contract unjust enrichment S68 S69 S70 S71 S72 ICA necessaries minor reimbursement interested finder mistake obligation no agreement court imposes"]],
  ["CON4","Penalty and liquidated damages","S.74 ICA: Where sum named in contract as amount payable on breach - court allows reasonable compensation not exceeding that sum (whether or not actual damage proved). English law distinction (penalty vs liquidated damages - only LD enforceable) does not strictly apply in India. In India: any stipulated sum is a ceiling; court can award less if actual damage is less. Test: was it a genuine pre-estimate of damage or unconscionable? SC in ONGC v Saw Pipes (2003): S.74 allows enforcement of agreed amount if reasonable.","Contracts","Legal Concepts","Contract Law",["penalty liquidated damages S74 ICA ceiling reasonable court English distinction ONGC Saw Pipes 2003 actual damage prove not required"]],
  ["CON5","Specific performance - updated law","S.10 SRA 1963 (as amended 2018): Specific performance now a right (not discretion) if contract is otherwise enforceable. The 2018 Amendment to Specific Relief Act: (a) made specific performance a right except for certain contracts; (b) introduced substituted performance (S.20); (c) allowed infrastructure contracts to be specifically enforced; (d) increased limitations on discretion to refuse. Post-2018: much harder for courts to refuse specific performance if contract is valid and enforceable.","Contracts","Legal Concepts","Contract Law",["specific performance SRA S10 2018 amendment right not discretion substituted performance S20 infrastructure harder refuse valid enforceable court"]],
  // Property Law concepts
  ["PROP1","Adverse possession - complete law","Requirements for adverse possession: (1) actual possession; (2) open and notorious; (3) exclusive; (4) hostile to true owner; (5) continuous for 12 years (LA Article 65). After 12 years of adverse possession, true owner's right to sue extinguished (S.27 LA). Adverse possessor can apply for declaration of title. SC in Hemaji Waghela v Shree Dhrangadhra Chemical Works: adverse possession is a right recognized by law; owner could have acted but didn't. Karnataka amendment: cannot claim adverse possession of government land.","Property","Legal Concepts","Property Law",["adverse possession 12 years open notorious exclusive hostile continuous actual possession extinguished S27 LA Article 65 Hemaji Waghela declaration title Karnataka government"]],
  ["PROP2","Easements - types and creation","An easement is the right of one landowner to use the land of another for a specific purpose (Easements Act 1882). Types: way (right of way); light and air; support (S.7); water; customary easements. Creation: express grant; implied grant; prescription (20 years under Limitation Act); necessity; quasi-easement; custom. Termination: merger; abandonment; unity of ownership. Easement runs with the dominant tenement (benefits) and burdens the servient tenement.","Property","Legal Concepts","Property Law",["easement right way light air support water customary Easements Act 1882 express implied prescription 20 years necessity dominant servient terminate merger abandonment"]],
  ["PROP3","Partition of joint family property","Mitakshara: partition by metes and bounds; all coparceners (now including daughters per 2005 amendment) can demand partition; demand is sufficient - no need of court; actual division is partition. After 2005 HSA amendment: daughter is a coparcener and can demand partition. Mode of partition: by agreement; by institution of a suit for partition; by will (not a partition); by arbitration; by conversion to another religion (not automatic now). Arthandale: partition of specific items of joint property.","Property","Legal Concepts","Property Law",["partition Mitakshara coparcener daughter 2005 HSA metes bounds demand court mode agreement suit arbitration conversion religion specific items joint family"]],
  // Criminal Law concepts
  ["CRIM1","Charge - Joinder and misjoinder","S.218-221 CrPC: Separate charges for separate offences - one charge per offence per trial is the rule. Exceptions (joinder): S.219 - same transaction within 12 months; S.220 - acts forming same transaction; S.221 - if accused doubted which offence committed. Misjoinder of charges: does not vitiate trial unless prejudice shown (S.215 CrPC). Prejudice is the ultimate test. Framing of charges without application of mind is a ground for revision.","Criminal","Legal Concepts","Criminal Procedure",["charge joinder misjoinder S218 S219 S220 S221 CrPC same transaction 12 months separate S215 prejudice vitiate framing revision"]],
  ["CRIM2","Acquittal - types and consequences","Order of acquittal: (1) discharge under S.227 CrPC - at framing stage, not on merits; (2) acquittal on merits after trial - S.232/235 CrPC. Consequences of acquittal: bars re-trial on same offence (S.300 CrPC / Art.20(2)); prosecution can appeal against acquittal (S.378 CrPC); High Court can reverse acquittal and convict (Chandrappa v State of Karnataka 2007 - SC guidelines for appellate court in acquittal cases). Fresh evidence: cannot be led in appeal against acquittal except in limited circumstances.","Criminal","Legal Concepts","Criminal Procedure",["acquittal discharge S227 S232 S235 CrPC bar re-trial S300 Art 20(2) appeal S378 High Court reverse conviction Chandrappa 2007 guidelines fresh evidence limited"]],
  ["CRIM3","Sentencing guidelines in India","S.235(2) CrPC: mandatory hearing on sentence. Bachan Singh: aggravating and mitigating factors for death penalty. Age of accused: SC has commuted death sentences for juveniles. Mental illness at time of sentencing: ground for commutation. Victim impact statement: increasingly considered. Reformative theory: juvenile justice. Deterrence: Nirbhaya case - enhanced minimum sentences for rape. 3-tier sentencing: minimum; default; maximum. Probation: S.360 CrPC, Probation of Offenders Act 1958.","Criminal","Legal Concepts","Criminal Procedure",["sentencing S235(2) CrPC mandatory hearing Bachan Singh aggravating mitigating age mental illness victim impact reformative deterrence Nirbhaya probation minimum default maximum"]],
  ["CRIM4","Anticipatory bail - key principles","S.438 CrPC: application to Sessions or High Court. Conditions commonly imposed: cooperation with investigation; not tamper with evidence; not leave country; report to police. SC in Gurbaksh Singh Sibbia (1980): S.438 is a device to secure personal liberty; should be given liberal construction; conditions should be the norm not blanket refusal. Sushila Aggarwal (2020) 5-judge bench: anticipatory bail does not automatically expire at first court appearance; can continue till trial ends. SC in P. Chidambaram: economic offences - special considerations.","Criminal","Legal Concepts","Criminal Procedure",["anticipatory bail S438 CrPC Sessions High Court Gurbaksh Singh Sibbia 1980 personal liberty Sushila Aggarwal 2020 conditions cooperation evidence tamper P Chidambaram economic"]],
  // Constitutional Law concepts
  ["CONST1","Basic structure doctrine - detailed","Kesavananda Bharati v State of Kerala (1973): 7:6 majority established that Parliament cannot amend the 'basic structure' of the Constitution. Basic structure (non-exhaustive): supremacy of Constitution; republican and democratic form; secular character; separation of powers; judicial review; unity and integrity of India; rule of law; federalism; fundamental rights. Tests: substantive limits on Article 368 power. SC has applied it to invalidate: 39th Amendment (immunity of PM's election - Indira Gandhi case 1975); 42nd Amendment provisions; 99th Amendment (NJAC - Judges appointment - 2015).","Constitutional","Legal Concepts","Constitutional Law",["basic structure Kesavananda 1973 Parliament amend supremacy republican secular separation powers judicial review unity federalism fundamental rights Article 368 NJAC 99th amendment Indira Gandhi 39th"]],
  ["CONST2","Doctrine of proportionality in India","Introduced in India through Puttaswamy (2017) privacy judgment. Test (4-step): (1) Legality - law must exist; (2) Legitimate aim - state interest; (3) Proportionality stricto sensu - means-end proportionality; (4) Procedural safeguards. Applied in: Anuradha Bhasin v Union of India (2020) - internet shutdown; MHC v Rajasthan (2019) - police detention; PUCL v Union of India - encounter deaths. Replaces older 'reasonable restrictions' standard in Art.19 cases with a more rigorous European-style test.","Constitutional","Legal Concepts","Constitutional Law",["proportionality Puttaswamy 2017 legality legitimate aim means-end procedural safeguards internet shutdown Anuradha Bhasin encounter deaths PUCL Article 19 European test"]],
  ["CONST3","Doctrine of eclipse and severability","Eclipse: a pre-constitutional law that is inconsistent with fundamental rights (Art.13(1)) is not void but 'eclipsed' or overshadowed - if the fundamental right is amended/abridged, the eclipsed law revives. Bhikaji Narain Dhakras (1955). Severability: if an Act contains both valid and invalid provisions, the valid provisions can be severed and applied - provided they are severable and can stand independently. Doctrine of severability is based on legislative intention - what would legislature have done if it knew the invalid part was gone?","Constitutional","Legal Concepts","Constitutional Law",["eclipse pre-constitutional law inconsistent fundamental rights Art 13(1) overshadowed revive Bhikaji Narain 1955 severability valid invalid severed legislative intention"]],
  ["CONST4","Judicial review - scope in India","Article 226 (High Court) and Article 32 (Supreme Court): writs of habeas corpus, mandamus, certiorari, prohibition, quo warranto. Scope: review executive and legislative action for: violation of fundamental rights; violation of constitutional provisions; procedural impropriety; irrationality/Wednesbury unreasonableness; illegality; proportionality (post-Puttaswamy). SC in Marbury v Madison equivalent in India: Kesavananda affirmed judicial review as basic structure. Limitations: legislative privilege (Art.105, 194); High policy matters (defense, foreign policy); national security.","Constitutional","Legal Concepts","Constitutional Law",["judicial review Article 226 32 High Court Supreme Court writs habeas corpus mandamus certiorari prohibition quo warranto procedural impropriety Wednesbury proportionality limitations legislative"]],
  // Environmental Law concepts
  ["ENV1","Public Trust Doctrine in India","The State holds natural resources (air, water, forests, seashore, rivers) as a trustee for the public - they cannot be transferred to private parties for private use. SC in MC Mehta v Kamal Nath (1997): the government cannot grant mining lease in forest land on banks of Beas river - violated public trust doctrine. The doctrine is now a recognized principle of Indian environmental law. Applied in: coastal regulation; forest diversion; river pollution; spectrum allocation (2G case).","Environment","Legal Concepts","Environmental Law",["public trust doctrine State natural resources trustee not private MC Mehta Kamal Nath 1997 mining forest Beas river coastal forest diversion spectrum 2G"]],
  ["ENV2","Sustainable development - India's approach","Sustainable development means development that meets the needs of the present without compromising the ability of future generations to meet their own needs (Brundtland Commission 1987). SC in Vellore Citizens Forum (1996): sustainable development is part of customary international law and part of Indian law. Components: intergenerational equity; use of natural resources; precautionary principle; polluter pays. NGT has applied sustainable development in Yamuna/Ganga pollution cases; Western Ghats protection; Aravalli mining ban.","Environment","Legal Concepts","Environmental Law",["sustainable development Brundtland 1987 Vellore Citizens Forum 1996 intergenerational equity precautionary polluter pays customary international Indian law NGT Yamuna Ganga Aravalli"]],
];
LEGAL_CONCEPTS.forEach(([sec,title,desc,ch,cht,cat,kw])=>
  add("Indian Legal System","LEGAL",sec,title,desc,ch,cht,cat,kw));

// ─────────────────────────────────────────────────────────────────────────────
// SECTION H: Indian Evidence Act - remaining sections in full
// ─────────────────────────────────────────────────────────────────────────────
const IEA_EXTRA = [
  ["23","Admissions in civil cases when relevant","In civil cases, no admission is relevant if it is made either upon an express condition that evidence of it is not to be given, or under circumstances from which the court can infer that the parties agreed together that evidence of it should not be given. This protects 'without prejudice' communications.","3","Admissions","Evidence Law",["IEA S23 admissions civil cases without prejudice express condition infer agree evidence not given"]],
  ["30","Consideration of proved confession affecting person making it and others jointly under trial","When more persons than one are being tried jointly for the same offence, and a confession made by one of such persons affecting himself and some other of such persons is proved, the court may take into consideration such confession as against such other person.","3","Admissions","Evidence Law",["IEA S30 confession co-accused jointly tried affect himself others proved court take into consideration"]],
  ["31","Admissions not conclusive proof but may estop","Admissions are not conclusive proof of the matters admitted but they may operate as estoppels under the provisions hereinafter contained.","3","Admissions","Evidence Law",["IEA S31 admissions not conclusive proof operate estoppel"]],
  ["35","Relevancy of entry in public record or electronic record made in performance of duty","An entry in any public or other official book, register or electronic record, stating a fact in issue or relevant fact, and made by a public servant in the discharge of his official duty, or by any other person in performance of a duty specially enjoined by the law of the country in which such book, register or electronic record is kept, is itself a relevant fact.","4","Documentary Evidence","Evidence Law",["IEA S35 public record entry official duty register electronic fact in issue public servant law enjoined relevant"]],
  ["37","Relevancy of acts of state","Facts showing the existence of any general custom or right shall be proved by evidence of particular instances in which the custom or right has been claimed, recognised, or exercised, or in which its exercise was disputed, asserted, or departed from.","4","Documentary Evidence","Evidence Law",["IEA S37 general custom right particular instances claimed recognised exercised disputed departed"]],
  ["38","Relevancy of acts of state","Any opinion of an expert has been expressed in any treatise commonly offered for sale, and the ground of the opinion are stated in such treatise, such opinion may be proved by the production of such treatise if the author is dead or cannot be found, or has become incapable of giving evidence, or cannot be called as a witness without an amount of delay or expense which the Court regards as unreasonable.","5","Opinions","Evidence Law",["IEA S38 expert opinion treatise dead cannot found incapable call witness delay expense court reasonable"]],
  ["48","Opinion as to existence of right or custom - when relevant","When the court has to form an opinion as to the existence of any general custom or right, the opinions, as to the existence of such custom or right, of persons who would be likely to know of its existence if it existed, are relevant.","5","Opinion of Third Persons","Evidence Law",["IEA S48 opinion general custom right persons likely know existence relevant court form"]],
  ["49","Opinions of experts as to usages, tenets etc.","When the court has to form an opinion as to the usages and tenets of any body of men or family, the constitution and government of any religious or charitable foundation, or the meaning of words or terms used in particular districts or by particular classes of people, the opinions of persons having special means of knowledge thereon, are relevant.","5","Opinion of Third Persons","Evidence Law",["IEA S49 opinion usages tenets religious charitable constitution government words terms particular district class persons special knowledge relevant"]],
  ["50","Opinion on relationship when relevant","When the court has to form an opinion as to the relationship of one person to another, the opinion, expressed by conduct, as to the existence of such relationship, of any person who, as a member of the family or otherwise, has special means of knowledge on the subject, is a relevant fact.","5","Opinion of Third Persons","Evidence Law",["IEA S50 opinion relationship person family special means knowledge conduct relevant court form"]],
  ["51","Grounds of opinion when relevant","Whenever the opinion of any living person is relevant, the grounds on which such opinion is based are also relevant.","5","Opinion of Third Persons","Evidence Law",["IEA S51 grounds opinion relevant living person based also relevant"]],
  ["53A","Evidence of character or previous sexual experience not relevant in certain cases","In a prosecution for an offence under section 376, 376A, 376AB, 376B, 376C, 376D, 376DA, 376DB or 376E of the Indian Penal Code or for attempt to commit any such offence, where the question of consent is in issue, evidence of the character of the victim or of such person's previous sexual experience with any person shall not be relevant on the issue of such consent or the quality of consent.","5","Character","Evidence Law",["IEA S53A character previous sexual experience not relevant consent rape prosecution section 376 victim quality consent"]],
  ["54","Previous bad character not relevant except in reply","In criminal proceedings the fact that the accused person has a bad character is irrelevant, unless evidence has been given that he has a good character, in which case it becomes relevant. Section 53 - good character admissible; S.54 - bad character only in reply.","5","Character","Evidence Law",["IEA S54 bad character criminal not relevant unless good character evidence given first S53 reply rebuttal"]],
  ["62","Primary evidence - original document","Primary evidence means the document itself produced for the inspection of the court. Where a document is executed in several parts, each part is primary evidence of the document. Original of an electronic record stored in a computer is primary evidence.","8","Documentary Evidence","Evidence Law",["IEA S62 primary evidence original document inspection court executed parts electronic computer stored"]],
  ["63","Secondary evidence - types","Secondary evidence means and includes: (a) certified copies; (b) copies made from the original by mechanical processes; (c) copies made from or compared with the original; (d) counterparts of documents; (e) oral accounts of contents of document given by persons who have seen it.","8","Documentary Evidence","Evidence Law",["IEA S63 secondary evidence types certified copy mechanical process compared counterpart oral account seen document"]],
  ["68","Proof of execution of document required by law to be attested","If a document is required by law to be attested, it shall not be used as evidence until one attesting witness at least has been called for the purpose of proving its execution, if there be an attesting witness alive, and subject to the process of the court and capable of giving evidence.","8","Documentary Evidence","Evidence Law",["IEA S68 attested document proof execution one attesting witness called alive court capable evidence requirement law"]],
  ["69","Proof where no attesting witness found","If no such attesting witness can be found, or if the document purports to have been executed in the United Kingdom, it must be proved that the attestation of one attesting witness at least is in the handwriting of that person, and that the subscription of the executant is in the handwriting of the executant.","8","Documentary Evidence","Evidence Law",["IEA S69 no attesting witness found UK handwriting one attestation subscription executant proved"]],
  ["70","Admission of execution by party to attested document","The admission of a party to an attested document of its execution by himself shall be sufficient proof of its execution as against him, though it be a document required by law to be attested.","8","Documentary Evidence","Evidence Law",["IEA S70 admission execution attested document party sufficient proof against him law"]],
  ["71","Proof when attesting witness denies execution","If the attesting witness denies or does not recollect the execution of the document, its execution may be proved by other evidence.","8","Documentary Evidence","Evidence Law",["IEA S71 attesting witness denies does not recollect execution proved other evidence"]],
  ["72","Proof of document not required by law to be attested","An unattested document which by law is not required to be attested may be proved by any secondary evidence of its contents, subject to the rules of secondary evidence.","8","Documentary Evidence","Evidence Law",["IEA S72 unattested document not required law secondary evidence contents proved"]],
  ["73A","Proof as to digital signature","In order to ascertain whether a digital signature is that of the person by whom it purports to have been affixed, the court may direct that person or the Certifying Authority to produce the Digital Signature Certificate.","8","Documentary Evidence","Evidence Law",["IEA S73A digital signature Certifying Authority produce certificate ascertain court direct"]],
  ["78","Proof of other official documents","The following public documents may be proved as follows: acts, orders or notifications of the Central Government in the Official Gazette - by the Gazette itself; acts of the Legislature - by copies published by authority.","9","Public Documents","Evidence Law",["IEA S78 official documents acts notifications Official Gazette Central Government Legislature copies published authority"]],
  ["82","Presumption as to documents produced as record of evidence given in judicial proceedings","Whenever any document is produced purporting to be a record of evidence given in a judicial proceeding, the court shall presume that the document is genuine; any statement therein is in accordance with law; evidence was duly taken.","10","Presumptions","Evidence Law",["IEA S82 presumption record evidence judicial proceedings genuine statement accordance law duly taken document"]],
  ["84","Presumption as to collection of laws and reports of decisions","The court shall presume the genuineness of every book purporting to be printed or published under the authority of the Government of any country, and to contain any of the laws of that country; and of every book purporting to contain reports of decisions of the Courts of such country.","10","Presumptions","Evidence Law",["IEA S84 presumption laws printed government country reports decisions courts book published authority"]],
  ["86","Presumption as to certified copies of foreign judicial records","The court may presume that any document purporting to be a certified copy of any judicial record of any country not forming part of India is genuine and accurate, if the document purports to be certified in the manner usual in that country and the court has no reason to believe otherwise.","10","Presumptions","Evidence Law",["IEA S86 presumption certified copy foreign judicial record genuine accurate usual manner country court"]],
  ["87","Presumption as to books, maps and charts","The court may presume that any book to which it may refer for information on matters of public or general interest, and that any published map or chart, the statements of which are relevant facts, and which is produced for the inspection of the court, was written and published by the person, and at the time and place, by whom or at which it purports to have been written or published.","10","Presumptions","Evidence Law",["IEA S87 presumption books maps charts public interest relevant facts written published person time place court"]],
  ["88","Presumption as to telegraphic messages","The court may presume that a message forwarded from a telegraph office to the person to whom such message purports to be addressed corresponds with a message delivered for transmission at the office from which the message purports to be sent; but the court shall not make any presumption as to the person by whom such message was delivered for transmission.","10","Presumptions","Evidence Law",["IEA S88 presumption telegraphic message forwarded corresponds delivered transmission office person addressed"]],
  ["90","Presumption as to documents 30 years old","Where any document, purporting or proved to be 30 years old, is produced from any custody which the court in the particular case considers proper, the court may presume that the signature and every other part of such document which purports to be in the handwriting of any particular person is in that person's handwriting, and in the case of a document executed or attested, that it was duly executed and attested by the persons by whom it purports to be executed and attested.","10","Presumptions","Evidence Law",["IEA S90 30 years old document presumption signature handwriting duly executed attested custody proper court"]],
  ["114","Court may presume existence of certain facts","The court may presume the existence of any fact which it thinks likely to have happened, regard being had to the common course of natural events, human conduct and public and private business. Illustrations: (a) mail delivered in ordinary course; (b) judicial acts done properly; (c) birth during marriage legitimate; (d) possession within 2 years is possession under colour of right.","10","Presumptions","Evidence Law",["IEA S114 court may presume existence fact common course natural events human conduct illustrations mail judicial acts birth possession"]],
  ["123","Evidence as to affairs of State - privilege","No one shall be permitted to give any evidence derived from unpublished official records relating to any affairs of State, except with the permission of the officer at the head of the department concerned, who shall give or withhold such permission as he thinks fit.","13","Production and Effect of Evidence","Evidence Law",["IEA S123 state privilege unpublished official records affairs of state department head permission withhold"]],
  ["125","Information as to commission of offences","No Magistrate or Police Officer shall be compelled to say whence he got any information as to the commission of any offence, and no Revenue Officer shall be compelled to say whence he got any information as to the commission of any offence against the public revenue.","13","Production and Effect of Evidence","Evidence Law",["IEA S125 information offence Magistrate police revenue officer compelled say source whence commission privilege"]],
  ["127","Power of Judge to put questions or order production","The judge may, in order to discover or to obtain proper proof of relevant facts, ask any question he pleases, in any form, at any time, of any witness, or of the parties, about any fact relevant or irrelevant; and may order the production of any document or thing.","14","Examination of Witnesses","Evidence Law",["IEA S127 judge question any form any time witness parties relevant irrelevant production document thing power"]],
  ["128","Power of jury or assessors to put questions","In cases tried by jury or with assessors, the jury or assessors may put any questions to the witnesses, through or by leave of the judge, which the judge himself might put and which he considers proper.","14","Examination of Witnesses","Evidence Law",["IEA S128 jury assessors questions witnesses through leave judge proper consider trial"]],
  ["130","Witness not excused from producing documents","A witness summoned to produce a document shall bring it to the court, notwithstanding any objection which there may be to its production or to its admissibility.","14","Examination of Witnesses","Evidence Law",["IEA S130 witness summon produce document bring court objection admissibility production notwithstanding"]],
  ["133","Accomplice","An accomplice shall be a competent witness against an accused person; and a conviction is not illegal merely because it proceeds upon the uncorroborated testimony of an accomplice.","13","Production and Effect of Evidence","Evidence Law",["IEA S133 accomplice competent witness accused conviction not illegal uncorroborated testimony"]],
  ["134","Number of witnesses","No particular number of witnesses shall in any case be required for the proof of any fact.","13","Production and Effect of Evidence","Evidence Law",["IEA S134 no minimum number witnesses proof fact required any case"]],
  ["135","Order of production and examination of witnesses","The order in which witnesses are produced and examined shall be regulated by the law and practice for the time being relating to civil and criminal procedure respectively, and, in the absence of any such law, by the discretion of the court.","13","Production and Effect of Evidence","Evidence Law",["IEA S135 order production examination witnesses law practice civil criminal discretion court"]],
  ["136","Judge to decide as to admissibility of evidence","When either party proposes to give evidence of any fact, the judge may ask the party proposing to give the evidence in what manner the alleged fact, if proved, would be relevant; and the judge shall admit the evidence if he thinks that the fact, if proved, would be relevant, and not otherwise.","14","Examination of Witnesses","Evidence Law",["IEA S136 judge decide admissibility fact proposed relevant proved admit not otherwise manner relevance"]],
  ["154","Court may permit leading questions to hostile witness","The court may, in its discretion, permit the person who calls a witness to put any questions to him which might be put in cross-examination by the adverse party - when the witness is hostile.","14","Examination of Witnesses","Evidence Law",["IEA S154 hostile witness leading questions permitted court discretion cross-examination adverse party"]],
  ["156","Questions not to be asked without reasonable grounds","No such question as is referred to in section 148 ought to be asked, unless the person asking it has reasonable grounds for thinking that the imputation which it conveys is well-founded.","14","Examination of Witnesses","Evidence Law",["IEA S156 questions reasonable grounds imputation well-founded section 148 character credit"]],
  ["159","Refreshing memory","A witness may, while under examination, refresh his memory by referring to any writing made by himself at the time of the transaction concerning which he is questioned, or so soon afterwards that the court considers it likely that the transaction was at that time fresh in his memory.","14","Examination of Witnesses","Evidence Law",["IEA S159 refresh memory writing made transaction concerned time soon afterwards fresh court considers"]],
  ["160","Testimony to facts stated in document mentioned in S.159","A witness may also testify to facts mentioned in any such document as is mentioned in section 159, although he has no specific recollection of the facts themselves, if he is sure that the facts were correctly recorded in the document.","14","Examination of Witnesses","Evidence Law",["IEA S160 testimony facts document S159 no specific recollection correctly recorded sure"]],
  ["161","Right of adverse party as to writing used to refresh memory","Any writing referred to under the provisions of the two last sections must be produced and shown to the adverse party if he requires it; such party may, if he pleases, cross-examine the witness thereupon.","14","Examination of Witnesses","Evidence Law",["IEA S161 adverse party writing refresh memory produced shown cross-examine witness thereupon sections 159 160"]],
  ["162","Production of documents","A witness summoned to produce a document shall, if it is in his possession or power, bring it to court, notwithstanding any objection which there may be to its production or to its admissibility. The validity of any such objection shall be decided on by the court.","14","Examination of Witnesses","Evidence Law",["IEA S162 production document witness possession power bring court objection admissibility decided"]],
  ["164","No question can be asked about certain communications","No witness who is not a party to a suit shall be compelled to disclose any confidential communication which has taken place between him and the party to the suit.","13","Production and Effect of Evidence","Evidence Law",["IEA S164 confidential communication not a party suit witness not compelled disclose"]],
  ["165","Power of judge to put questions","The judge may, in order to discover or to obtain proper proof of relevant facts, ask any question he pleases, in any form, at any time.","14","Examination of Witnesses","Evidence Law",["IEA S165 judge power questions any form time discover proper proof relevant facts"]],
];
IEA_EXTRA.forEach(([sec,title,desc,ch,cht,cat,kw])=>
  add("Indian Evidence Act, 1872","IEA",sec,title,desc,ch,cht,cat,kw));

// Write output
fs.writeFileSync(OUT, JSON.stringify(all, null, 1), 'utf8');
const sizeKB = Math.round(fs.statSync(OUT).size / 1024);
console.log(`\n✓ mega_bulk.json written`);
console.log(`  Total entries: ${all.length}`);
console.log(`  File size: ${sizeKB} KB`);
console.log('\nBreakdown by act:');
const counts = {};
all.forEach(e => { counts[e.act_short] = (counts[e.act_short]||0)+1; });
Object.entries(counts).sort((a,b)=>b[1]-a[1])
  .forEach(([k,v]) => console.log(`  ${k.padEnd(10)} ${v}`));
